// Screen shell mirrors Networks: same 860 x min(660px) frame, same header band
// with a title and a right-hand action, so moving between the two shelf
// destinations doesn't resize or restyle the window.
// Map one GET /agents entity into the row shape used here. Read-only: agent
// management writes are session-only and unreachable with an API key.
function mapLiveAgent(a) {
  const TINTS = ["#4C6FD4", "#B4553F", "#3E8E7E", "#C64B8C", "#7B5EA7", "#E8A317"];
  const name = a.name || "agent";
  let h = 0;
  for (let i = 0; i < name.length; i++) h = (h * 31 + name.charCodeAt(i)) >>> 0;
  const rel = (iso) => {
    const t = Date.parse(iso);
    if (Number.isNaN(t)) return "";
    const s = Math.max(0, Math.floor((Date.now() - t) / 1000));
    if (s < 60) return `${s}s ago`;
    const m = Math.floor(s / 60);
    return m < 60 ? `${m}m ago` : `${Math.floor(m / 60)}h ago`;
  };
  // An agent registered against your account is connected, whether or not it
  // has checked in lately. `lastSeenAt` is null on every agent the API has
  // handed back so far, and reading that as "detected" left every row shut:
  // only a connected row opens, so the detail behind it was unreachable.
  // The heartbeat is a separate fact and says for itself when there isn't one.
  const active = a.status ? a.status === "active" : true;
  const owner = String((currentMe() || {}).name || "").trim().split(/\s+/)[0];
  return {
    id: a.id,
    name,
    live: true,
    initial: (name[0] || "a").toLowerCase(),
    tint: TINTS[h % TINTS.length],
    state: active ? "connected" : "detected",
    on: active,
    // the one agent the API says carries negotiations
    negotiates: !!a.handleNegotiations,
    connectedAs: a.description || (owner ? `${owner}'s ${name.toLowerCase()}` : name.toLowerCase()),
    heartbeat: a.lastSeenAt ? rel(a.lastSeenAt) : "",
  };
}

function Agents({ onClose }) {
  // Live-only: no demo runtimes. The list is populated by fetchRegistered (the
  // account's registered agents) and the local harness scan below.
  const [agents, setAgents] = useState([]);
  const [expanded, setExpanded] = useState(null);
  const [hermesWork, setHermesWork] = useState(null);
  // Read off the live agent list; "index" is the builtin negotiator fallback.
  const [negotiator, setNegotiator] = useState("index");

  // Which local runtimes are already registered on the account: personal
  // agents matched by name (lowercased). Server-side system agents never map
  // to runtime rows — the Index row in the list is the local builtin, pinned
  // on, and it doubles as the negotiator fallback in the picker below.
  const [registered, setRegistered] = useState({});
  const fetchRegistered = () => {
    if (!window.IndexApp || !window.IndexApp.isAuthed()) return Promise.resolve();
    const client = window.IndexApp.getClient();
    if (!client) return Promise.resolve();
    return client.agents.list()
      .then((res) => {
        const list = window.IndexApp.normalizeList(res, "agents")
          .filter(a => a.type !== "system");
        // Rebuild from scratch so agents deactivated or deleted elsewhere
        // (e.g. on the web) drop their stale state here.
        const next = {};
        list.forEach((a) => {
          const row = mapLiveAgent(a);
          next[row.name.toLowerCase()] = row;
        });
        setRegistered(next);
        const carries = list.find(a => a.handleNegotiations && a.status !== "inactive");
        setNegotiator(carries ? carries.id : "index");
      })
      .catch(() => {});
  };
  useEffect(() => { fetchRegistered(); }, []);

  // Real inventory: the Swift shell scans the login-shell PATH for known
  // agent CLIs (claude, codex, goose, …). Until the first scan answers, or
  // when there is no bridge (browser preview), the demo list stands in.
  const [detected, setDetected] = useState(null);
  const scan = () => (window.IndexApp && window.IndexApp.detectHarnesses)
    ? window.IndexApp.detectHarnesses().then((list) => {
        if (list) setDetected(list.map(h => ({
          id: `local-${h.id}`, name: h.label, path: h.path,
          wired: h.wired === "true",
        })));
      })
    : Promise.resolve();
  useEffect(() => { scan(); }, []);
  useEffect(() => {
    if (!window.IndexApp || !window.IndexApp.onHermesProgress) return;
    return window.IndexApp.onHermesProgress((step) => {
      if (!step) return;
      setHermesWork(w => w ? { ...w, lines: [...w.lines, step] } : w);
    });
  }, []);

  // "check again" re-scans local binaries AND re-fetches registration status
  // from the API; the spin holds long enough to read.
  const [checking, setChecking] = useState(false);
  const checkTimer = useRef(null);
  useEffect(() => () => clearTimeout(checkTimer.current), []);
  const check = () => {
    if (checking) return;
    setChecking(true);
    Promise.all([scan(), fetchRegistered()]).then(() => {
      checkTimer.current = setTimeout(() => setChecking(false), 700);
    });
  };

  // The switch wires a local runtime to your account, it does not create an
  // agent: agents are created and deleted in the web app with a signed-in
  // session. Hermes is the runtime with local wiring — the Swift shell writes
  // your stored key into ~/.hermes/.env and installs the Index plugin.
  const busy = useRef(new Set());
  const toggleOn = (id) => {
    // browser preview: the demo rows keep their local flip
    if (detected === null) {
      setAgents(list => list.map(a => {
        if (a.id !== id) return a;
        return { ...a, on: !a.on };
      }));
      return;
    }
    if (!window.IndexApp || !window.IndexApp.isAuthed()) {
      alert("sign in first — wiring a runtime needs your account key.");
      return;
    }
    const row = rows.find(a => a.id === id);
    if (!row || row.name.toLowerCase() !== "hermes") return;
    if (busy.current.has(id)) return;
    busy.current.add(id);
    const done = () => busy.current.delete(id);
    const turningOn = !row.on;
    setHermesWork({
      turningOn,
      lines: [turningOn ? "wiring Hermes to this account" : "unwiring Hermes"],
      error: null,
      done: false,
    });
    const wire = row.on
      ? window.IndexApp.teardownHermes()
      : window.IndexApp.setupHermes();
    wire
      .then((r) => {
        if (!(r && r.ok)) {
          setHermesWork(w => w ? { ...w, error: (r && r.error) || "unknown error" } : w);
          return;
        }
        setDetected(list => (list || []).map(h =>
          h.name.toLowerCase() === "hermes" ? { ...h, wired: turningOn } : h
        ));
        setHermesWork(null);
      })
      .catch((err) => {
        setHermesWork(w => w ? { ...w, error: String(err && err.message || err) } : w);
      })
      .then(done, done);
  };

  // Your negotiator's picture is derived from your account id (see myAgent in
  // primitives), so it is the same everywhere with nothing to configure here.
  const myNegotiator = myAgent();

  // Rows are the builtin Index runtime plus the detected local runtimes.
  // Index leads the list: always on, not switchable — it is the system
  // default that carries negotiations when nothing else does. A local
  // runtime already registered on the account (matched by name) wears its
  // live record: connected state, real id, on = active. Everything else is
  // detected, and stays detected until that agent is added in the web app.
  const indexRow = {
    id:"index", name:"Index", state:"system default", on:true, builtin:true,
  };
  const rows = [indexRow, ...(detected === null ? agents : detected.map(d => {
    const live = registered[d.name.toLowerCase()];
    // hermes is the only runtime with local wiring, so it is the only switch
    // that does anything here.
    const wireable = d.name.toLowerCase() === "hermes";
    const wired = wireable && d.wired;
    return live
      ? { ...live, path: d.path, wireable, on: wireable ? wired : live.on }
      : { id: d.id, name: d.name, state: "detected", on: !!wired,
          connectedAs: "", heartbeat: "", path: d.path, wireable };
  }))];

  // Which runtime carries negotiations is picked in the web app, where you
  // have a session; here it is read off the agent list.
  const negotiatorRow = rows.find(a => a.id === negotiator);
  const negotiatorLabel = negotiatorRow && !negotiatorRow.builtin
    ? `${negotiatorRow.name} · on this mac`
    : "Index · system default";

  return (
    <div style={{
      position:"absolute", inset:0,
      display:"grid", placeItems:"center",
      gridTemplateColumns:"minmax(0, 1fr)",
      padding:"56px 40px", overflow:"auto",
    }}>
      {/* Takes the screen it is given: tall enough that the runtimes and the
          negotiator both sit above the fold on a laptop, and it still gives way
          to the desktop margin on a short one. */}
      <div style={{
        width:860, maxWidth:"100%",
        height:"min(880px, calc(100vh - 96px))",
      }}>
        <MacWindow
          title="agents"
          onClose={onClose}
          style={{ height:"100%", minHeight:0 }}>

          <div style={{ padding:"18px 24px 14px", borderBottom:"2px solid #000" }}>
            <div style={{
              display:"flex", alignItems:"center", justifyContent:"space-between", gap:12,
            }}>
              <h2 style={{
                margin:0,
                fontFamily:"var(--mac-mono)", fontSize:22, fontWeight:700, color:"#000",
              }}>agents</h2>
              <ActionButton
                title="look for agent runtimes again"
                onClick={check}>
                <span style={{ display:"inline-flex", alignItems:"center", gap:7 }}>
                  <span style={{
                    display:"inline-block",
                    animation: checking ? "mac-orbit 0.7s linear infinite" : "none",
                  }}>↻</span>
                  {checking ? "checking" : "check again"}
                </span>
              </ActionButton>
            </div>
            <p style={{
              margin:"10px 0 0", maxWidth:560,
              fontFamily:"var(--mac-sans)", fontSize:13, lineHeight:1.5, color:"var(--ink-2)",
            }}>
              agents on this mac can act for you. add and remove them in the
              web app; this is what's running here.
            </p>
          </div>

          <div className="mac-scroll" style={{
            flex:"1 1 auto", minHeight:0, overflowY:"auto",
            padding:"18px 24px 22px",
          }}>
            {/* What's on the machine first, then who speaks for you out of it.
                the inventory is the concrete thing, the negotiator is the choice
                you make from it. */}
            <RuleLabel size={13}>runtimes</RuleLabel>
            <p style={{
              margin:"8px 0 10px", maxWidth:560,
              fontFamily:"var(--mac-sans)", fontSize:12, lineHeight:1.5, color:"var(--ink-2)",
            }}>
              connected agents can create signals and negotiate for you.
            </p>

            {/* one framed block; rows divide it, so it reads as a single
                inventory of this machine rather than four loose cards */}
            <div style={{
              border:"1px solid #000", background:"#fff",
              boxShadow:"2px 2px 0 rgba(0,0,0,0.22)",
              opacity: checking ? 0.5 : 1,
              transition:"opacity 140ms linear",
            }}>
              {rows.map((a, i) => (
                <AgentRow
                  key={a.id}
                  last={i === rows.length - 1}
                  agent={a}
                  expanded={expanded === a.id}
                  onToggleExpand={(id) => setExpanded(e => e === id ? null : id)}
                  onToggleOn={toggleOn}
                  work={a.name.toLowerCase() === "hermes" ? hermesWork : null}
                />
              ))}
              {/* index is always here, so "empty" means no local runtimes */}
              {rows.length === 1 && (
                <div style={{
                  padding:"12px", borderTop:"1px solid #000",
                  fontFamily:"var(--mac-mono)", fontSize:11, color:"var(--ink-3)",
                }}>no other agent runtimes found on this mac</div>
              )}
            </div>

            <SectionRule size={13}>negotiator agent</SectionRule>
            {/* no measure cap on this one: it is one sentence and it should
                stay one line, so it gets the full width of the pane */}
            <p style={{
              margin:"8px 0 12px",
              fontFamily:"var(--mac-sans)", fontSize:12, lineHeight:1.5, color:"var(--ink-2)",
            }}>
              one agent speaks for you in the network. pick which runtime carries it.
            </p>

            <NegotiatorProfile
              agent={myNegotiator}
              runtimeLabel={negotiatorLabel}
            />
          </div>
        </MacWindow>
      </div>
    </div>
  );
}

// ─── apps/mac/src/ui/history.jsx ──────────────────────────────────────────────
// Negotiation history, the wire log of everything your agent has negotiated
// on your behalf. Reached from the account menu on the hub.
//
// Two modes. "stream" is the default: every turn from every thread merged into
// one chronological tail -f, so you see the agent juggling several
// counterparties at once. "grouped" slides in a thread drawer on the left and
// narrows the log to the selected thread, the master/detail view.
//
// Live data comes from GET /users/:id/negotiations (threads with counterparty,
// outcome, and per-turn agent reasoning). No demo fallback, signed out the
// wire is simply empty.

// A thread's result bucket: won (opportunity), lost, or still open.
function negoResult(th) {
  if (!th.outcome) return "open";
  return th.outcome.hasOpportunity ? "won" : "lost";
}
function negoFirstName(th) {
  return ((th.counterparty && th.counterparty.name) || "unknown").split(/\s+/)[0].toLowerCase();
}
function negoClock(iso) {
  const d = new Date(iso);
  if (isNaN(d)) return "--:--:--";
  const p = (n) => String(n).padStart(2, "0");
  return `${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`;
}
function negoRoles(suggestedRoles) {
  if (!Array.isArray(suggestedRoles) || suggestedRoles.length === 0) return null;
  return suggestedRoles.map((r) => (r && r.role) || r).filter(Boolean).join(" / ");
}

const NEGO_RESULT_GLYPH = {
  won:  { g: "✓", color: "#000" },
  lost: { g: "✕", color: "var(--ink-warn)" },
  open: { g: "●", color: "#FF8A00" },
};

/* ---------- log lines ---------- */

// One turn in the wire log. `withTag` is on in stream mode, off in a
// single-thread transcript where the counterparty is already the context.
function NegoTurnLine({ th, turn, you, withTag, onTag }) {
  const roles = negoRoles(turn.suggestedRoles);
  return (
    <div className="fade-up" style={{ display:"grid", gap:2 }}>
      <div style={{
        display:"flex", alignItems:"baseline", gap:8,
        fontFamily:"var(--mac-mono)", fontSize:11, color:"#000",
      }}>
        <span style={{ color:"var(--ink-3)", flex:"0 0 auto" }}>{negoClock(turn.createdAt)}</span>
        {withTag && (
          <button onClick={() => onTag && onTag(th)} style={{
            flex:"0 0 auto", fontFamily:"var(--mac-mono)", fontSize:10,
            border:"1px solid #000", background:"#fff", color:"#000",
            padding:"0 5px", cursor:"pointer", width:76, textAlign:"left",
            overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap",
          }}
          onMouseEnter={(e) => { e.currentTarget.style.background = "#000"; e.currentTarget.style.color = "#FF8A00"; }}
          onMouseLeave={(e) => { e.currentTarget.style.background = "#fff"; e.currentTarget.style.color = "#000"; }}
          >{negoFirstName(th)}</button>
        )}
        <span style={{ fontWeight:700, flex:"0 0 auto" }}>
          {you ? "you.agent" : `${negoFirstName(th)}.agent`}
        </span>
        <span style={{ flex:"0 0 auto" }}>{you ? "→" : "←"}</span>
        <span style={{
          flex:"0 0 auto", textTransform:"uppercase", letterSpacing:1,
          background: you ? "#000" : "#fff", color: you ? "#fff" : "#000",
          border:"1px solid #000", padding:"0 6px", fontSize:10,
        }}>{turn.action || "unknown"}</span>
        {roles && <span style={{ color:"var(--ink-2)", fontSize:10 }}>roles: {roles}</span>}
      </div>
      {turn.reasoning && (
        <div style={{
          marginLeft: withTag ? 156 : 72,
          fontFamily:"var(--mac-mono)", fontSize:11, lineHeight:1.45,
          color:"var(--ink-2)", maxWidth:560,
        }}>"{turn.reasoning}"</div>
      )}
    </div>
  );
}

// Outcome as an event in the stream, the moment a thread closed.
function NegoClosedLine({ th, withTag }) {
  const r = negoResult(th);
  const { g } = NEGO_RESULT_GLYPH[r];
  const detail = r === "won"
    ? `opportunity${th.outcome.role ? ` · ${th.outcome.role}` : ""}`
    : (th.outcome && th.outcome.reason) || "no opportunity";
  return (
    <div className="fade-up" style={{
      display:"flex", alignItems:"center", gap:8,
      fontFamily:"var(--mac-mono)", fontSize:10, letterSpacing:0.5,
      color: r === "won" ? "#000" : "var(--ink-2)",
    }}>
      <span style={{ color:"var(--ink-4)" }}>{negoClock(th.statusTimestamp || th.updatedAt)}</span>
      <span style={{ flex:"0 0 auto" }}>───</span>
      <span style={{ fontWeight:700 }}>
        {withTag ? `${negoFirstName(th)} · ` : ""}closed {g} {detail}
      </span>
      <span style={{ flex:1, borderTop:"1px dashed var(--ink-4)" }}/>
    </div>
  );
}

/* ---------- grouped drawer ---------- */

function NegoThreadRow({ th, active, onPick }) {
  const r = negoResult(th);
  const { g, color } = NEGO_RESULT_GLYPH[r];
  return (
    <button onClick={onPick} style={{
      display:"grid", gridTemplateColumns:"1fr auto auto", gap:8,
      alignItems:"center", width:"100%", textAlign:"left",
      padding:"7px 10px", cursor:"pointer",
      border:"1px solid #000",
      background: active ? "#000" : "#fff",
      color: active ? "#FF8A00" : "#000",
      fontFamily:"var(--mac-mono)", fontSize:11,
    }}>
      <span style={{ overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap", fontWeight:700 }}>
        {negoFirstName(th)}
      </span>
      <span style={{ color: active ? "#FF8A00" : "var(--ink-3)", fontSize:10 }}>
        {th.turns.length}t
      </span>
      <span style={{ color: active ? "#FF8A00" : color, fontWeight:700 }}>{g}</span>
    </button>
  );
}

/* ---------- the screen ---------- */

function NegotiationHistory({ onClose }) {
  const live = !!(window.IndexApp && window.IndexApp.isAuthed());
  const myId = (window.INDEX_DATA && window.INDEX_DATA.ME && window.INDEX_DATA.ME.id) || null;
  const [threads, setThreads] = useState(null);   // null = loading
  const [mode, setMode] = useState("stream");
  const [filter, setFilter] = useState("all");
  const [selectedId, setSelectedId] = useState(null);

  useEffect(() => {
    let dead = false;
    const load = async () => {
      if (live && myId && window.IndexApp.getClient) {
        try {
          const res = await window.IndexApp.getClient().users.negotiations(myId, { limit: 50 });
          if (!dead) setThreads(res.negotiations || []);
          return;
        } catch (e) { /* keep whatever is shown; empty state below covers first load */ }
      }
      if (!dead) setThreads((prev) => prev || []);
    };
    load();
    const t = setInterval(load, 3000);   // same cadence as the radar
    return () => { dead = true; clearInterval(t); };
  }, [live, myId]);

  const all = threads || [];
  const counts = useMemo(() => ({
    won:  all.filter((t) => negoResult(t) === "won").length,
    lost: all.filter((t) => negoResult(t) === "lost").length,
    open: all.filter((t) => negoResult(t) === "open").length,
  }), [all]);
  const filtered = useMemo(
    () => filter === "all" ? all : all.filter((t) => negoResult(t) === filter),
    [all, filter],
  );
  const selected = filtered.find((t) => t.id === selectedId) || filtered[0] || null;

  // Stream: flatten every turn + every close into one time-ordered log.
  const events = useMemo(() => {
    const src = mode === "grouped" ? (selected ? [selected] : []) : filtered;
    const evs = [];
    for (const th of src) {
      for (const turn of (th.turns || [])) {
        evs.push({ kind:"turn", t: Date.parse(turn.createdAt) || 0, th, turn });
      }
      if (th.outcome) {
        evs.push({ kind:"closed", t: Date.parse(th.statusTimestamp || th.updatedAt) || 0, th });
      }
    }
    return evs.sort((a, b) => a.t - b.t);
  }, [filtered, mode, selected]);

  // tail -f scroll: pinned to bottom unless the user scrolls up.
  const scrollRef = useRef(null);
  const pinned = useRef(true);
  const [away, setAway] = useState(false);
  React.useLayoutEffect(() => {
    if (pinned.current && scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [events, mode]);
  const onScroll = (e) => {
    const el = e.currentTarget;
    const atBottom = el.scrollHeight - el.scrollTop - el.clientHeight < 24;
    pinned.current = atBottom;
    setAway(!atBottom);
  };
  const jumpLive = () => {
    pinned.current = true; setAway(false);
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  };

  const isYou = (turn) => !!turn.speaker && (turn.speaker.id === myId || turn.speaker.id === "me");
  const openGrouped = (th) => { setMode("grouped"); setSelectedId(th.id); };

  const log = (
    <div style={{ position:"relative", display:"grid", minHeight:0 }}>
      <div ref={scrollRef} onScroll={onScroll} className="mac-scroll" style={{
        overflowY:"auto", padding:"14px 18px",
        display:"flex", flexDirection:"column",
      }}>
        <div style={{ marginTop:"auto", display:"flex", flexDirection:"column", gap:10 }}>
          {threads === null ? (
            <div style={{ fontFamily:"var(--mac-mono)", fontSize:11, color:"var(--ink-2)" }}>
              reading the wire<span className="mac-caret"/>
            </div>
          ) : events.length === 0 ? (
            <div style={{
              border:"1px dashed #000", padding:"18px 16px",
              fontFamily:"var(--mac-mono)", fontSize:12, color:"var(--ink-2)",
            }}>
              nothing on the wire yet, your agent logs every negotiation here
              as it happens.
            </div>
          ) : events.map((ev, i) =>
            ev.kind === "closed"
              ? <NegoClosedLine key={`c-${ev.th.id}-${i}`} th={ev.th} withTag={mode === "stream"}/>
              : <NegoTurnLine key={`t-${ev.th.id}-${i}`} th={ev.th} turn={ev.turn}
                  you={isYou(ev.turn)} withTag={mode === "stream"} onTag={openGrouped}/>
          )}
          {/* live cursor, the wire stays open */}
          <span style={{
            fontFamily:"var(--mac-mono)", fontSize:12, color:"#FF8A00",
            animation:"mac-blink 1s steps(2) infinite",
          }}>▌</span>
        </div>
      </div>
      {away && (
        <button onClick={jumpLive} style={{
          position:"absolute", left:"50%", transform:"translateX(-50%)", bottom:10,
          fontFamily:"var(--mac-mono)", fontSize:11, padding:"3px 12px",
          border:"1px solid #000", background:"#000", color:"#FF8A00",
          cursor:"pointer", boxShadow:"1px 1px 0 rgba(0,0,0,0.2)",
        }}>↓ jump to live</button>
      )}
    </div>
  );

  return (
    <div style={{
      position:"absolute", inset:0,
      display:"grid", placeItems:"center",
      padding:"56px 40px", overflow:"auto",
    }}>
      <div style={{ width:1000, maxWidth:"100%", height:"calc(100vh - 112px)" }}>
        <MacWindow title="negotiation history" onClose={onClose} style={{ height:"100%" }}>
          <div style={{ display:"grid", gridTemplateRows:"auto 1fr auto", flex:1, minHeight:0 }}>

            {/* header: lifetime counters + mode/filter controls */}
            <div style={{
              padding:"10px 16px", borderBottom:"2px solid #000", background:"#fff",
              display:"flex", alignItems:"center", gap:12, flexWrap:"wrap",
            }}>
              <span style={{ fontFamily:"var(--mac-mono)", fontSize:11, color:"#000" }}>
                <b>{all.length}</b> sessions · <b>{counts.won}</b> ✓ · <b>{counts.lost}</b> ✕ · <b>{counts.open}</b> open
              </span>
              <div style={{ flex:1 }}/>
              <MacSegmented value={mode} onChange={setMode} options={[
                { value:"stream", label:"stream" }, { value:"grouped", label:"grouped" },
              ]}/>
              <MacSegmented value={filter} onChange={(f) => { setFilter(f); setSelectedId(null); }} options={[
                { value:"all", label:"all" }, { value:"won", label:"won" },
                { value:"lost", label:"lost" }, { value:"open", label:"open" },
              ]}/>
            </div>

            {/* body: bare stream, or drawer + single-thread transcript */}
            {mode === "stream" ? log : (
              <div style={{
                display:"grid", gridTemplateColumns:"220px 1fr", minHeight:0,
              }}>
                <div className="mac-scroll" style={{
                  overflowY:"auto", padding:"12px 10px",
                  borderRight:"2px solid #000", background:"#F2F0EC",
                  display:"flex", flexDirection:"column", gap:6, alignContent:"start",
                }}>
                  {filtered.map((th) => (
                    <NegoThreadRow key={th.id} th={th}
                      active={selected && selected.id === th.id}
                      onPick={() => setSelectedId(th.id)}/>
                  ))}
                  {filtered.length === 0 && (
                    <span style={{ fontFamily:"var(--mac-mono)", fontSize:11, color:"var(--ink-2)", padding:6 }}>
                      no sessions here.
                    </span>
                  )}
                </div>
                {log}
              </div>
            )}

            {/* footer status line */}
            <div style={{
              borderTop:"1px solid #000", padding:"7px 16px", background:"#fff",
              display:"flex", alignItems:"center", gap:10,
              fontFamily:"var(--mac-mono)", fontSize:10, color:"var(--ink-2)", letterSpacing:0.4,
            }}>
              <LiveDot size={6}/>
              <span>{away ? "paused · scrolled into history" : "following"}</span>
              <span>·</span>
              <span>{counts.open} open session{counts.open === 1 ? "" : "s"}</span>
              {mode === "grouped" && selected && (
                <React.Fragment>
                  <span>·</span>
                  <span>viewing {negoFirstName(selected)} · {selected.turns.length} turns</span>
                </React.Fragment>
              )}
              <div style={{ flex:1 }}/>
              <span>{live ? "live wire" : "offline"}</span>
            </div>
          </div>
        </MacWindow>
      </div>
    </div>
  );
}

window.NegotiationHistory = NegotiationHistory;

// ─── apps/mac/src/ui/intents.jsx ──────────────────────────────────────────────
/* global useIndexEnv */
// Intents, Workbench shelf of saved searches. This is the app's hub:
// brand promise ("find your others"), active signals, and the entry point for
// a new signal.

/* How tall the signals shelf is allowed to get. Six rows, then it scrolls.
   IntentRow's own height and the shelf's gap live here so the cap stays
   correct if either changes; a hardcoded pixel maxHeight would quietly start
   cutting a row in half. */
const SHELF_ROW_H = 72;
const SHELF_ROW_GAP = 8;
const SHELF_VISIBLE_ROWS = 6;

/* ---------- account shelf ---------- */

// Account shelf avatar — same bauhaus fallback as everywhere else.
function InitialsTile({ id, name, size = 46, photo }) {
  return (
    <Avatar id={id} name={name} photo={photo} size={size}/>
  );
}

// The communities you belong to. Intentionally quiet, no border or shadow, so
// it reads as a shelf item rather than competing with the account row below it.
// The glyph occupies the same 34px block as the account tile and the label uses
// the same size and weight, so the two rows line up even though their fills
// differ on purpose.
function NetworksRow({ count, pending, onClick }) {
  return (
    <button
      onClick={onClick}
      style={{
        display:"flex", alignItems:"center", gap:12, width:"100%",
        padding:"5px 13px", cursor:"pointer", textAlign:"left",
        border:"none", background:"#F2F0EC",
      }}>
      <span style={{
        flex:"0 0 auto", width:34, height:34,
        display:"flex", flexDirection:"column",
        alignItems:"center", justifyContent:"center", gap:5,
      }}>
        {[0, 1].map(r => (
          <span key={r} style={{ display:"flex", gap:4, alignItems:"center" }}>
            <span style={{ width:4, height:4, background:"#000" }}/>
            <span style={{ width:13, height:4, background:"#000" }}/>
          </span>
        ))}
      </span>
      <span style={{
        flex:1, minWidth:0,
        fontFamily:"var(--mac-mono)", fontSize:13, fontWeight:700, color:"#000",
      }}>networks ({count})</span>
      <QCount
        n={pending}
        muted={!pending}
        title={`${pending} waiting on you — people asking to join`}
      />
    </button>
  );
}

// Handing out a link is its own errand, so it gets its own shelf row rather
// than living inside one network's access tab. Chain-link mark, same 34px
// block as the rows around it.
function InviteRow({ onClick }) {
  return (
    <button
      onClick={onClick}
      style={{
        display:"flex", alignItems:"center", gap:12, width:"100%",
        padding:"5px 13px", cursor:"pointer", textAlign:"left",
        border:"none", background:"#F2F0EC",
      }}>
      <span style={{
        flex:"0 0 auto", width:34, height:34,
        display:"flex", alignItems:"center", justifyContent:"center",
      }}>
        <span style={{ width:9, height:9, border:"2px solid #000" }}/>
        <span style={{ width:7, height:2, background:"#000" }}/>
        <span style={{ width:9, height:9, border:"2px solid #000" }}/>
      </span>
      <span style={{
        flex:1, minWidth:0,
        fontFamily:"var(--mac-mono)", fontSize:13, fontWeight:700, color:"#000",
      }}>invite</span>
    </button>
  );
}

// The agents destination. Same quiet shelf treatment as the networks row above
// it: both are destinations, not settings, so both get a plain glyph. Your
// negotiator's picture belongs where the agent is speaking, not on a row whose
// job is "take me to the agents screen", where next to the networks mark it
// read as a stray photo in an icon column.
function AgentsRow({ count, onClick }) {
  return (
    <button
      onClick={onClick}
      style={{
        display:"flex", alignItems:"center", gap:12, width:"100%",
        padding:"5px 13px", cursor:"pointer", textAlign:"left",
        border:"none", background:"#F2F0EC",
      }}>
      <span style={{
        flex:"0 0 auto", width:34, height:34,
        display:"grid", placeItems:"center",
      }}>
        <AgentGlyph size={26}/>
      </span>
      <span style={{
        flex:1, minWidth:0,
        fontFamily:"var(--mac-mono)", fontSize:13, fontWeight:700, color:"#000",
      }}>agents ({count})</span>
    </button>
  );
}

// The account row. Click it for the account menu, closes on outside click or
// Escape, like a real menubar menu. Opens upward: it's the last thing in the
// column, so there's headroom above and none below.
function UserMenu({ me, onSelect }) {
  const [open, setOpen] = useState(false);
  const wrapRef = useRef(null);

  useEffect(() => {
    if (!open) return;
    const onDown = (e) => {
      if (wrapRef.current && !wrapRef.current.contains(e.target)) setOpen(false);
    };
    // capture + preventDefault so this menu takes the Escape before the
    // window-closing handler in primitives sees it
    const onKey = (e) => {
      if (e.key !== "Escape") return;
      e.preventDefault();
      setOpen(false);
    };
    document.addEventListener("mousedown", onDown, true);
    document.addEventListener("keydown", onKey, true);
    return () => {
      document.removeEventListener("mousedown", onDown, true);
      document.removeEventListener("keydown", onKey, true);
    };
  }, [open]);

  // "your network" moved out to its own shelf row above.
  const ITEMS = [
    { id: "profile",  label: "settings" },
    { id: "settings", label: "notifications" },
    { id: "history",  label: "negotiation history" },
    { id: "signout",  label: "sign out", danger: true },
  ];

  const pick = (item) => { setOpen(false); onSelect && onSelect(item.id); };
  // Destructive rows keep the app's warn treatment on hover, the same one the
  // archive gadget uses: red stays red and the row washes pink. Inverting them
  // to black-and-orange like the ordinary rows dropped the one colour that says
  // this one is different, at the exact moment the pointer is on it.
  const rowHover = (on, danger) => (e) => {
    e.currentTarget.style.background = on ? (danger ? "#FFF3F3" : "#000") : "transparent";
    e.currentTarget.style.color = danger ? "var(--ink-warn)" : (on ? "#FF8A00" : "#000");
  };

  return (
    <div ref={wrapRef} style={{ position:"relative", width:"100%" }}>
      <button
        onClick={() => setOpen(o => !o)}
        aria-haspopup="menu"
        aria-expanded={open}
        style={{
          display:"flex", alignItems:"center", gap:11, width:"100%",
          padding:"7px 11px", textAlign:"left", cursor:"pointer",
          border:"1px solid #000", background: open ? "#F2EFE6" : "#fff",
        }}>
        <InitialsTile id={me.id} name={me.name} size={34} photo={me.photo}/>
        <span style={{ flex:1, minWidth:0 }}>
          <span style={{
            display:"block",
            fontFamily:"var(--mac-mono)", fontSize:13, fontWeight:700, color:"#000",
          }}>{me.name}</span>
        </span>
        <span style={{
          flex:"0 0 auto",
          fontFamily:"var(--mac-mono)", fontSize:12, color:"#000",
          transform: open ? "rotate(180deg)" : "none",
        }}>▲</span>
      </button>

      {open && (
        <div role="menu" className="fade-up" style={{
          position:"absolute", bottom:"calc(100% + 6px)", left:0, zIndex:40,
          minWidth:200, width:"100%", background:"#fff",
          border:"1px solid #000", boxShadow:"3px 3px 0 rgba(0,0,0,0.22)",
          padding:"4px 0",
        }}>
          {ITEMS.map(item => (
            <button
              key={item.id}
              role="menuitem"
              onClick={() => pick(item)}
              onMouseEnter={rowHover(true, item.danger)}
              onMouseLeave={rowHover(false, item.danger)}
              style={{
                display:"block", width:"100%", textAlign:"left",
                padding:"6px 12px", border:"none", background:"transparent",
                fontFamily:"var(--mac-sans)", fontSize:12, cursor:"pointer",
                color: item.danger ? "var(--ink-warn)" : "#000",
                fontWeight: item.danger ? 600 : 400,
                borderTop: item.danger ? "1px solid #000" : "none",
                marginTop: item.danger ? 4 : 0,
              }}>{item.label}</button>
          ))}
        </div>
      )}
    </div>
  );
}

function Intents({ onPickExisting, onNew, onBack, onOpenView, onSignOut, fresh = false }) {
  const env = useIndexEnv();
  // Live-only: empty until the snapshot loads. AGENTS has no live snapshot in
  // this view yet, so the count is the builtin Index (always on) until the
  // agents pane loads the registered runtimes.
  const ME = env.me || {};
  const NETWORKS = env.networks || [];
  const AGENTS = [];
  const joinedCount = NETWORKS.filter(n => n.joined !== false).length;
  const pendingJoins = NETWORKS.reduce((sum, n) => sum + (n.pendingJoinCount || 0), 0);
  const agentCount  = 1 + AGENTS.filter(a => a.state === "connected").length;

  useEffect(() => {
    if (!env.live || !env.refreshNetworks) return;
    env.refreshNetworks();
  }, [env.live, env.refreshNetworks]);

  useEffect(() => {
    if (!env.live || !env.refreshIntents) return;
    env.refreshIntents();
  }, [env.live, env.refreshIntents]);

  // A just-onboarded user has no signals yet, the hub opens empty.
  const [signals, setSignals] = useState(() => fresh ? [] : (env.data.INTENTS || []));
  useEffect(() => {
    setSignals(fresh ? [] : (env.data.INTENTS || []));
  }, [env.data, fresh]);

  const [hovered, setHovered] = useState(null);
  const [showAgents, setShowAgents] = useState(false);
  const [showInvite, setShowInvite] = useState(false);

  // Width the shelf's scrollbar takes when it appears, so the pinned
  // new-signal row below can line up with the rows inside. Measured rather
  // than hardcoded to 16px, it's zero whenever the list fits.
  const shelfRef = useRef(null);
  const [shelfGutter, setShelfGutter] = useState(0);
  useEffect(() => {
    const el = shelfRef.current;
    if (!el) { setShelfGutter(0); return; }
    const measure = () => setShelfGutter(el.offsetWidth - el.clientWidth);
    measure();
    if (typeof ResizeObserver === "undefined") return;
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, [signals.length, showAgents]);

  // Settings, networks and negotiations are owned by the app shell, so that the
  // Index and View menus open the same screens; the hub only asks for one.
  const onAccountSelect = (id) => {
    if (id === "profile")  onOpenView && onOpenView("settings", "profile");
    if (id === "history")  onOpenView && onOpenView("negotiations");
    if (id === "settings") onOpenView && onOpenView("settings", "notify");
    if (id === "signout")  onSignOut && onSignOut();
  };

  // Agents takes over the whole surface, it's a screen, not a sheet.
  if (showAgents) {
    return (
      <Agents
        onClose={() => setShowAgents(false)}
      />
    );
  }

  if (showInvite) {
    return (
      <InviteNetworks
        networks={NETWORKS}
        onClose={() => setShowInvite(false)}
      />
    );
  }

  const visible  = signals.filter(i => i.status !== "archived");
  const active   = visible.filter(i => i.status === "active");
  const idle     = visible.filter(i => i.status === "idle");
  const paused   = visible.filter(i => i.status === "paused");
  const ordered  = [...active, ...idle, ...paused];

  return (
    <div style={{
      position:"absolute", inset:0,
      display:"grid", placeItems:"center",
      // an explicit track: the implicit `auto` one takes the 980px wrapper as
      // its floor, so `maxWidth:100%` below resolves against 980 rather than
      // against the room actually available and the window overhangs the desktop
      gridTemplateColumns:"minmax(0, 1fr)",
      padding:"56px 40px", overflow:"auto",
    }}>
      <div style={{
        width: 980,
        maxWidth:"100%",
        minWidth: 0,
        maxHeight: "calc(100vh - 112px)",
      }}>
        {/* the shelf inside already says "your signals"; the title bar only has
            to say which app the window belongs to */}
        <MacWindow title="index" onClose={onBack} style={{ maxHeight: "calc(100vh - 112px)", minHeight: "min(560px, calc(100vh - 112px))" }}>
          <div style={{
            padding:"22px 28px 20px",
            display:"grid",
            // fluid, not px floors: 260+360+gap+padding is wider than the
            // window once it's narrow, and the tracks would keep their floor
            // and push the signal list out through the right-hand frame
            gridTemplateColumns:"minmax(0, 0.85fr) minmax(0, 1.15fr)",
            gap:24,
            flex:1,
            minHeight:0,
          }}>
            <div style={{
              minWidth:0,
              display:"flex",
              flexDirection:"column",
              gap:18,
              paddingRight:22,
              borderRight:"2px solid #000",
            }}>
              {/* takes the slack so the shelf below is pinned to the floor */}
              <div style={{
                flex:"1 1 auto", minHeight:0,
                display:"flex", flexDirection:"column", justifyContent:"center",
              }}>
                {onBack && (
                  <button onClick={onBack} style={{
                    fontFamily:"var(--mac-mono)", fontSize:11, color:"#000",
                    background:"transparent", border:"none", padding:0, cursor:"pointer",
                    marginBottom:16,
                  }}>← back</button>
                )}
                <h1 style={{
                  fontFamily:"var(--amiga-mono)", fontWeight:700,
                  fontSize:34, lineHeight:1.05, letterSpacing:-0.6,
                  margin:0, color:"#000",
                }}>
                  find your others.
                </h1>
                <p style={{
                  marginTop:12, color:"#000",
                  fontSize:13, lineHeight:1.5, maxWidth:540,
                  fontFamily:"var(--mac-sans)",
                }}>
                  start a signal. your agent takes it to other agents. when both
                  sides want it, you get the intro.
                </p>
              </div>

              {/* sidebar footer, sits on the pane's floor, not under the copy */}
              <div style={{ display:"grid", gap:9 }}>
                <NetworksRow count={joinedCount} pending={pendingJoins} onClick={() => onOpenView && onOpenView("networks")}/>
                <InviteRow onClick={() => setShowInvite(true)}/>
                <AgentsRow count={agentCount} onClick={() => setShowAgents(true)}/>
                <UserMenu me={ME} onSelect={onAccountSelect}/>
              </div>
            </div>

            <div style={{
              minWidth:0,
              minHeight:0,
              display:"flex",
              flexDirection:"column",
            }}>
              <RuleLabel>your signals</RuleLabel>
              <div style={{ height:8 }}/>

              {/* Sized to its content when the list is short (so the new-signal
                  row sits right under the last one), and capped at six rows
                  once it is long: past that the shelf reads as a backlog rather
                  than the set of things you are running, and "start a new
                  signal" drifts further down the screen. The rest scroll. */}
              <div ref={shelfRef} className="mac-scroll" style={{
                flex:"0 1 auto", minHeight:0, overflowY:"auto",
                maxHeight: SHELF_VISIBLE_ROWS * SHELF_ROW_H
                         + (SHELF_VISIBLE_ROWS - 1) * SHELF_ROW_GAP,
                display:"flex", flexDirection:"column", gap: SHELF_ROW_GAP,
                paddingRight: 6,
              }}>
                {/* No empty state: the blurb above already says what a signal
                    does, and an empty list whose only row is "start a new
                    signal" doesn't need a second box to explain itself. */}
                {ordered.map(intent => (
                  <IntentRow
                    key={intent.id}
                    intent={intent}
                    hovered={hovered === intent.id}
                    onHover={() => setHovered(intent.id)}
                    onLeave={() => {}}
                    onPick={() => onPickExisting(intent)}
                  />
                ))}
              </div>

              {/* Starting a signal is what this screen is for, so it sits
                  outside the shelf, a long list scrolls behind it rather than
                  pushing it out of reach. The right padding matches the rows
                  above, which sit clear of the scrollbar when one is showing. */}
              <div style={{
                flex:"0 0 auto", paddingTop:8, paddingRight: 6 + shelfGutter,
                // flex, so the row stretches the way it did as a child of the
                // shelf, a bare <button> shrinks to fit its label
                display:"flex", flexDirection:"column",
              }}>
                <NewIntentRow onClick={onNew}/>
              </div>
            </div>
          </div>
        </MacWindow>
      </div>
    </div>
  );
}

/* A signal reads as what it is after, not as a sentence about wanting it. The
   summary that comes back from the API is written as prose ("Receive feedback
   on a launch video for an AI product from designers, founders, ..."), so the
   shelf drops the opening verb, lowercases it, and cuts it at a word so no row
   ends mid-word. This is a display fix. Titles that arrive already shaped, and
   short enough to sit whole in a row, pass through untouched. */
const TITLE_MAX = 45;
const TITLE_LEAD = /^(receive|explore|find|discover|connect with|connect to|connect|meet|seeking|seek|looking for|look for|get)\s+/;

function signalTitle(raw) {
  const text = String(raw || "").trim().toLowerCase().replace(/\s+/g, " ").replace(TITLE_LEAD, "");
  if (!text) return "untitled signal";
  if (text.length <= TITLE_MAX) return text;
  const head = text.slice(0, TITLE_MAX + 1);
  const lastSpace = head.lastIndexOf(" ");
  const cut = lastSpace > 12 ? head.slice(0, lastSpace) : text.slice(0, TITLE_MAX);
  return cut.replace(/[\s,;:.·/+-]+$/, "") + "…";
}

/* What the signal is doing, in its own words: scanning, mid-negotiation with
   another agent, resolved, or ended. "running" said the process was alive
   without saying what it was doing with the time. */
function signalStatus(intent) {
  if (intent.status === "archived") return "closed";
  if (intent.status === "paused") return "paused";
  if (intent.matches > 0) return "matched";
  if ((intent.pipeline || {}).negotiating > 0) return "negotiating";
  return "live";
}

/* ---------- Single intent row ---------- */
function IntentRow({ intent, hovered, onHover, onLeave, onPick }) {
  const isPaused = intent.status === "paused";
  // Opportunities awaiting you (same number as the Hermes and web dashboards).
  const pending = intent.pending ?? 0;
  const hasQ = pending > 0;
  const statusLabel = signalStatus(intent);
  // the blink is the signal working. only the states that are actually running
  // get it, so a shelf of closed and matched rows stays still
  const running = statusLabel === "live" || statusLabel === "negotiating";

  return (
    <button
      onClick={onPick}
      onMouseEnter={onHover}
      onMouseLeave={onLeave}
      style={{
        textAlign:"left",
        padding: "0 16px",
        height: SHELF_ROW_H,
        // the shelf is a column flex container, so without this the rows
        // shrink to share whatever height is left instead of the shelf
        // scrolling, squashing every signal and pushing the question count
        // out through the row's own border
        flex: "0 0 auto",
        boxSizing: "border-box",
        border:"1px solid #000",
        background: hovered ? "#FFF6E8" : "#FFFFFF",
        boxShadow: hovered
          ? "inset 1px 1px 0 #FFD7A0, inset -1px -1px 0 #8A4500, 1px 1px 0 rgba(0,0,0,0.2)"
          : "inset 1px 1px 0 #fff, inset -1px -1px 0 var(--ink-3), 1px 1px 0 rgba(0,0,0,0.2)",
        display:"flex", alignItems:"center", gap: 14,
        cursor:"pointer",
        opacity: isPaused ? 0.62 : 1,
        fontFamily: "var(--mac-sans)",
      }}>
      {/* title + tiny status */}
      <div style={{ flex:1, minWidth:0, display:"grid", gap:4 }}>
        <div style={{
          fontFamily:"var(--amiga-title)", fontSize: 15.5,
          color:"#000", fontWeight: 500, letterSpacing:-0.1,
          lineHeight: 1.2,
          whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis",
        }} title={intent.title}>
          {signalTitle(intent.title)}
        </div>
        <span style={{
          display:"flex", alignItems:"center", gap:6,
          fontFamily:"var(--mac-mono)", fontSize:10, color:"var(--ink-2)",
          letterSpacing:1,
        }}>
          {running && <LiveDot size={6}/>}
          {statusLabel}
        </span>
      </div>

      {/* awaiting opportunities, the hero */}
      <QCount n={pending} muted={!hasQ}/>
    </button>
  );
}

/* ---------- "new intent" row: bottom of the shelf ---------- */
function NewIntentRow({ onClick }) {
  const [down, setDown] = useState(false);
  return (
    <button
      onClick={onClick}
      onMouseDown={() => setDown(true)}
      onMouseUp={() => setDown(false)}
      onMouseLeave={() => setDown(false)}
      style={{
        textAlign:"left",
        padding:"11px 16px",
        flex: "0 0 auto",
        border:"2px solid #000",
        background: down ? "#000" : "#FF8A00",
        color: down ? "#FF8A00" : "#000",
        cursor:"pointer",
        display:"flex", alignItems:"center", gap: 14,
        boxShadow: down
          ? "none"
          : "inset 1px 1px 0 #FFD7A0, inset -2px -2px 0 #8A4500, 3px 3px 0 rgba(0,0,0,0.22)",
        marginTop: 8,
      }}>
      <span style={{
        width: 24, height: 24,
        display:"grid", placeItems:"center",
        background: down ? "#FF8A00" : "#fff",
        color: "#000",
        border:"1px solid #000",
        boxShadow:"inset 1px 1px 0 #fff, inset -1px -1px 0 var(--ink-3)",
        fontFamily:"var(--mac-mono)", fontSize:16, fontWeight:700,
        flex:"0 0 auto",
      }}>+</span>
      <div style={{ display:"grid", gap:3 }}>
        <div style={{
          fontFamily:"var(--mac-sans)", fontSize: 15, fontWeight: 700,
          letterSpacing:-0.2,
        }}>new signal</div>
      </div>
    </button>
  );
}

window.Intents = Intents;

// ─── apps/mac/src/ui/new-intent.jsx ───────────────────────────────────────────
// NewIntent — the signal-creation flow. Mac System 6 chrome, conversational.
// + Calibrating screen.
//
// The agent asks, you answer, it asks again. The opening answer is the signal;
// each follow-up comes from /intents/clarify, which folds the answers back into
// the payload. Then you confirm what was written and it goes out everywhere.

// The opening prompt: the user's first answer IS the signal, handed to the
// agent to clarify. The examples are whole signals rather than categories, so
// picking one hands clarify the same kind of material typing would.
const INTENT_STEP = {
  id: "intent",
  kind: "ask",
  prompt: "who are you trying to meet right now?",
  placeholder: "type what you're looking for…",
  examples: [
    "want to meet cool ai people in nyc",
    "have a new business idea, want honest feedback from others",
    "looking for a cool open-source project to contribute to",
    "want to find a co-founder who's actually shipped something",
  ],
};

function NewIntent({ onDone, onBack }) {
  const live = !!(window.IndexApp && window.IndexApp.isAuthed());
  const client = live ? window.IndexApp.getClient() : null;

  // Completed turns drive the progress bar and the faded history; the current
  // step is the opening prompt, a clarifying question, or one of the two gates.
  const [turns, setTurns] = useState([]);
  const [step, setStep] = useState(() => INTENT_STEP);
  const [thinking, setThinking] = useState(false);
  const [draft, setDraft] = useState("");
  const [calibrating, setCalibrating] = useState(false);
  const [finalDescription, setFinalDescription] = useState("");
  const inputRef = useRef(null);

  // The payload as it currently reads. Clarify rewrites it; create persists it.
  const payloadRef = useRef("");
  const preparationReceiptRef = useRef("");
  const feedbackRef = useRef("");
  const queue = useRef([]);            // clarifying questions not yet asked
  const pending = useRef([]);          // answers not yet folded into the payload
  const askedRef = useRef(0);          // clarifying questions asked so far
  const cancelledRef = useRef(false);
  useEffect(() => () => { cancelledRef.current = true; }, []);

  const stepIdx = step.kind === "summary" ? 2 : turns.length > 0 ? 1 : 0;
  const stepId = step && step.id;

  useEffect(() => {
    setDraft("");
    if (inputRef.current) {
      setTimeout(() => inputRef.current && inputRef.current.focus(), 50);
    }
  }, [stepId, thinking]);

  const showQuestion = (question) => {
    askedRef.current += 1;
    setThinking(false);
    setStep({
      id: `q-${askedRef.current}-${Date.now()}`,
      kind: "ask",
      prompt: question.prompt,
      note: feedbackRef.current,
      placeholder: "type your answer…",
      examples: (question.options || []).map((option) => option.label).filter(Boolean),
    });
  };

  const showSummary = (note) => {
    setThinking(false);
    setStep({ id: `summary-${Date.now()}`, kind: "summary", note: note || "" });
  };

  // The agent could not be reached. The answers are kept, so retrying resumes
  // the same round rather than restarting the conversation.
  const showRetry = () => {
    setThinking(false);
    setStep({
      id: `retry-${Date.now()}`,
      kind: "retry",
      prompt: "couldn't reach your agent.",
      note: "your answers are kept.",
    });
  };

  // One clarification round: the answers gathered since the last one get folded
  // into the payload, and whatever is still worth asking comes back.
  const clarify = async () => {
    setThinking(true);
    try {
      const answers = pending.current;
      const result = await client.intents.clarify({
        payload: payloadRef.current,
        ...(answers.length > 0 ? { answers } : {}),
      });
      if (cancelledRef.current) return;
      payloadRef.current = result.payload;
      pending.current = [];
      if (result.status === "ready") {
        preparationReceiptRef.current = result.preparationReceipt;
        setFinalDescription(result.payload);
        showSummary();
      } else {
        feedbackRef.current = result.feedback;
        queue.current = result.questions;
        advance();
      }
    } catch (_e) {
      if (cancelledRef.current) return;
      showRetry();
    }
  };

  // Keep asking until preparation admits the complete draft.
  const advance = () => {
    if (queue.current.length > 0) { showQuestion(queue.current.shift()); return; }
    void clarify();
  };

  const submit = (value) => {
    const raw = value ?? draft;
    const answer = String(raw).trim();
    if (!answer) return;
    setTurns((prev) => [...prev, { id: step.id, prompt: step.prompt, answer }]);

    if (step.id === "intent") {
      payloadRef.current = answer;
      // Signed out (the prototype walkthrough) there is nothing to clarify
      // against; the caller renders the signal locally.
      if (!client) { setCalibrating(true); onDone({ intent: answer }, false, null); return; }
      void clarify();
      return;
    }
    pending.current = [...pending.current, { prompt: step.prompt, answer }];
    advance();
  };

  const create = async () => {
    if (calibrating || !finalDescription.trim() || finalDescription.length > 65_536) return;
    const description = finalDescription;
    setCalibrating(true);
    try {
      const created = await client.intents.create({ description, preparationReceipt: preparationReceiptRef.current });
      if (cancelledRef.current) return;
      onDone({ intent: description }, true, created.intentId);
    } catch (_e) {
      if (cancelledRef.current) return;
      setCalibrating(false);
      showSummary("that didn't go through — try again.");
    }
  };

  if (calibrating) return <Calibrating/>;

  return (
    <div style={{
      position:"absolute", inset:0,
      display:"grid", placeItems:"center",
      gridTemplateColumns:"minmax(0, 1fr)",
      padding:"56px 40px", overflow:"auto",
    }}>
      <div style={{
        width: 980, maxWidth:"100%",
        display:"grid", gridTemplateColumns:"minmax(0, 1.4fr) minmax(0, 1fr)", gap:18,
        height: "min(720px, calc(100vh - 128px))",
      }}>
        {/* LEFT, conversation window */}
        <MacWindow title="calibrating" onClose={onBack}>
          <div style={{
            padding:"18px 28px 12px",
            display:"flex", flexDirection:"column",
            flex:1, minHeight:0,
          }}>
            {/* top status row */}
            <div style={{
              display:"flex", alignItems:"center", gap:10, marginBottom:16,
            }}>
              <button onClick={onBack} style={{
                fontFamily:"var(--mac-mono)", fontSize:13, color:"#000",
                background:"transparent", border:"none", padding:0, cursor:"pointer",
              }}>← back</button>
              <div style={{ flex:1 }}/>
            </div>

            {/* progress, pinstripe segments */}
            <div style={{ display:"flex", gap:3, marginBottom:24 }}>
              {Array.from({ length: 3 }).map((_, i) => (
                <div key={i} style={{
                  flex:1, height:8,
                  border:"1px solid #000",
                  background: i < stepIdx
                    ? "#000"
                    : i === stepIdx
                      ? "repeating-linear-gradient(45deg, #000 0, #000 2px, #fff 2px, #fff 4px)"
                      : "#fff",
                }}/>
              ))}
            </div>

            <div className="mac-scroll" style={{
              flex:1, minHeight:0, overflowY:"auto",
              display:"flex", flexDirection:"column", gap:20,
              paddingRight:6, paddingBottom:18,
            }}>
              {turns.map((t) => (
                <PastTurn key={t.id} step={{ prompt: t.prompt }} answer={t.answer}/>
              ))}

              {thinking ? (
                <div key="thinking" className="fade-up" style={{ display:"grid", gap:10 }}>
                  <AgentBubble>
                    <span style={{
                      color:"var(--ink-2)", display:"inline-flex",
                      alignItems:"center",
                    }}>
                      <WorkingDots/>
                    </span>
                  </AgentBubble>
                </div>
              ) : step.kind === "retry" ? (
              <div key={step.id} className="fade-up" style={{ display:"grid", gap:12 }}>
                <AgentBubble>{step.prompt}</AgentBubble>
                <div style={{ marginLeft:36, display:"flex", alignItems:"center", gap:12 }}>
                  <Btn primary onClick={() => clarify()}>try again</Btn>
                  <span style={{
                    fontFamily:"var(--mac-mono)", fontSize:11, color:"var(--ink-2)",
                  }}>{step.note}</span>
                </div>
              </div>
              ) : step.kind === "summary" ? (
              <div key={step.id} className="fade-up" style={{ display:"grid", gap:12 }}>
                <AgentBubble>Here's your signal.</AgentBubble>
                <SignalSummaryCard
                  description={finalDescription}
                  onChange={setFinalDescription}
                  note={step.note}
                  onCreate={create}
                />
              </div>
              ) : (
              <div key={step.id} className="fade-up" style={{ display:"grid", gap:10 }}>
                <AgentBubble>{step.prompt}</AgentBubble>
                {step.note && <p style={{ marginLeft:36, fontSize:13, color:"var(--ink-2)" }}>{step.note}</p>}

                <div style={{ marginLeft:36, marginTop:10, display:"grid", gap:16 }}>
                  {/* type your own answer first, the suggestions are the
                      "or pick one" fallback, so they come after */}
                  <form onSubmit={(e) => { e.preventDefault(); submit(); }}
                    style={{ display:"flex", gap:12, alignItems:"center", maxWidth:560 }}>
                    <span style={{
                      fontFamily:"var(--mac-mono)",
                      fontSize: 17, color:"#000",
                    }}>›</span>
                    <input
                      ref={inputRef}
                      value={draft}
                      maxLength={65_536}
                      onChange={e => setDraft(e.target.value)}
                      placeholder={step.placeholder}
                      style={{
                        flex:1,
                        background:"#fff",
                        border:"none",
                        borderBottom:"1px solid #000",
                        outline:"none",
                        color:"#000",
                        fontFamily:"var(--mac-sans)",
                        fontSize: 16,
                        padding:"7px 0",
                      }}
                    />
                    <Btn primary disabled={!draft.trim()} onClick={() => submit()}>send ↵</Btn>
                  </form>
                  {step.examples && step.examples.length > 0 && (
                    <React.Fragment>
                      <div style={{
                        fontFamily:"var(--mac-mono)", fontSize:11, letterSpacing:1,
                        textTransform:"uppercase", color:"var(--ink-3)",
                      }}>or pick one</div>
                      <div style={{
                        display:"grid", gap:7, maxWidth:560,
                      }}>
                        {step.examples.map(ex => (
                          <SuggestChip key={ex} onClick={() => submit(ex)}>{ex}</SuggestChip>
                        ))}
                      </div>
                    </React.Fragment>
                  )}
                </div>
              </div>
              )}
            </div>
          </div>
        </MacWindow>

        {/* RIGHT, the field warming */}
        <MacWindow title="the field, warming">
          <NewIntentFieldPreview turns={turns} stepIdx={stepIdx}/>
        </MacWindow>
      </div>
    </div>
  );
}

