// Deterministic "why it expired" line for the summary view.
function expiryReason(person) {
  const R = [
    "the moment passed. they committed to something else before you replied.",
    "they went quiet, and your agent stopped surfacing them after a few days.",
    "the overlap cooled as your signal sharpened, and your edges drifted apart.",
    "they matched elsewhere first; your agent closed the thread to keep the radar clean.",
  ];
  const s = person.id || person.name || "x";
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
  return R[h % R.length];
}

// A plain bold heading in the reading face. The em-dash-and-tracked-caps
// treatment this replaced dressed up ordinary section labels as machine
// output; a heading over a paragraph is just a heading over a paragraph.
function SummarySection({ label, children }) {
  return (
    <div style={{ display:"grid", gap:5 }}>
      <div style={{
        fontFamily:"var(--mac-sans)", fontSize:12.5, fontWeight:700,
        color:"#000", letterSpacing:-0.1,
      }}>{label}</div>
      <div style={{ fontFamily:"var(--mac-sans)", fontSize:13, lineHeight:1.5, color:"#000" }}>
        {children}
      </div>
    </div>
  );
}

/* Summary of an expired person, opens in the 3rd window when you click one. */
function SummaryWindow({ person, onClose }) {
  return (
    <MacWindow title="summary" onClose={onClose} dismiss style={{ minHeight:0 }}>
      <div style={{ display:"grid", gridTemplateRows:"auto 1fr", gridTemplateColumns:"minmax(0, 1fr)", flex:1, minHeight:0, minWidth:0 }}>
        <div style={{
          padding:"12px 16px", borderBottom:"1px solid #000",
          display:"flex", gap:12, alignItems:"center", background:"#fff",
        }}>
          <Avatar id={person.userId || person.id} name={person.name} photo={person.photo} size={34}/>
          <div style={{ display:"grid", gap:2, minWidth:0 }}>
            <div style={{ fontFamily:"var(--amiga-title)", fontSize:15, fontWeight:600, color:"#000" }}>
              {person.name}
            </div>
            <div style={{
              fontFamily:"var(--mac-mono)", fontSize:10, color:"var(--ink-2)",
              letterSpacing:1, textTransform:"uppercase",
            }}>expired{person.location ? ` · ${person.location}` : ""}</div>
          </div>
        </div>

        <div className="mac-scroll" style={{
          overflowY:"auto", padding:"16px", display:"grid", gridTemplateColumns:"minmax(0, 1fr)", gap:16,
          alignContent:"start", background:"#fff",
        }}>
          <SummarySection label="what your agent found">
            {person.pitchFromAgent || person.blurb}
          </SummarySection>
          <SummarySection label="signals">
            <div style={{ display:"flex", flexWrap:"wrap", gap:5 }}>
              {(person.signals || []).map(s => (
                <span key={s} style={{
                  fontFamily:"var(--mac-mono)", fontSize:10, letterSpacing:0.3,
                  padding:"1px 6px", border:"1px solid #000",
                }}>{s}</span>
              ))}
            </div>
          </SummarySection>
          {person.overlap && person.overlap.length > 0 && (
            <SummarySection label="what you shared">
              {person.overlap.join(" · ")}
            </SummarySection>
          )}
          <SummarySection label="why it closed">
            {expiryReason(person)}
          </SummarySection>
          <SummarySection label="last seen">
            {person.distance}
          </SummarySection>
        </div>
      </div>
    </MacWindow>
  );
}

/* The card's fields overlap heavily by construction, the API mappers build
   `overlap` out of the same headline as `blurb`, and `signals` out of the same
   two strings as `location`/`distance`, so rendering every field gave the
   profile the same sentence three times under three different headings. This
   walks the fields in order of importance and drops anything already said. */
function normText(v) {
  return String(v == null ? "" : v).trim().toLowerCase().replace(/\s+/g, " ");
}

// "Feedback on Collaborative Interfaces: Luc Baracat", the header two lines
// up already says whose profile this is.
function stripSelfName(text, name) {
  const t = String(text || "").trim();
  const n = String(name || "").trim();
  if (!t || !n) return t;
  const esc = n.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return t.replace(new RegExp("\\s*[:\\u2013\\u2014-]\\s*" + esc + "\\s*$", "i"), "").trim() || t;
}

function profileContent(person) {
  const seen = new Set();
  const block = (v) => { const k = normText(v); if (k) seen.add(k); };
  const take = (v) => {
    const k = normText(v);
    if (!k || seen.has(k)) return null;
    seen.add(k);
    return String(v).trim();
  };

  // The headline and the shared-signal chips are both the system's summary of
  // this person, and neither is theirs. What the profile shows is the intro
  // they wrote about themselves, so the card's own blurb is only blocked here
  // to keep it from reappearing through another field.
  block(person.blurb);
  const bio = take(person.bio);
  // Prefer the presenter mainText (`detail`) for "why surfaced"; the short
  // narrator chip is the fallback when detail is missing or identical.
  const note = take(person.detail) || take(person.pitchFromAgent);
  // An entry that resolves to no address is left out rather than drawn as a
  // link that goes nowhere. See api/socials.mjs for what fails to resolve.
  const socials = (person.socials || []).filter(s => s && socialHrefOf(s));

  // `location` and `distance` are not what they sound like on a home card: the
  // mapper fills them with the section heading the card was grouped under and
  // its mutual-intents label, which is how "MEET THESE NEW CONNECTIONS ·
  // Aligned goals" ended up reading as this person's details. Both are the
  // system describing its own grouping, so neither belongs on their profile.
  const meta = [];
  if (person.mutuals > 0) {
    meta.push(`${person.mutuals} mutual${person.mutuals === 1 ? "" : "s"}`);
  }
  const via = String(person.introVia || "").trim();
  // "intro via Index" is the product telling you it's the product
  if (via && !/^index(\s*network)?$/i.test(via)) meta.push(`intro via ${via}`);

  return { bio, note, socials, meta };
}

/* A social link: the platform's mark and the username, nothing else. The
   normalizing lives in primitives so this and the settings editor agree on what
   a handle is. Bordered like a gadget rather than like the flat share chips
   above, because unlike those these are pressable. */
function SocialLink({ social }) {
  const [hover, setHover] = useState(false);
  const platform = socialPlatformOf(social);
  const href = socialHrefOf(social);
  const ink = hover ? "#fff" : "#000";
  return (
    <a href={href} target="_blank" rel="noreferrer noopener"
      title={`${platform} · ${href}`}
      onMouseEnter={() => setHover(true)} onMouseLeave={() => setHover(false)}
      style={{
        display:"inline-flex", alignItems:"center", gap:6,
        fontFamily:"var(--mac-mono)", fontSize:11, letterSpacing:0.2,
        padding:"4px 9px", border:"1px solid #000", textDecoration:"none",
        background: hover ? "#000" : "#fff",
        color: ink,
        boxShadow:"1px 1px 0 rgba(0,0,0,0.2)",
      }}>
      <SocialGlyph id={platform} size={13} color={ink}/>
      <span>{socialHandleOf(social)}</span>
    </a>
  );
}

/* A card opened from outside the app (an index:// link or a universal link).
   The route can land on any screen, including the hub where no signal is open
   and the radar's selection state does not exist, so it floats above whatever
   is showing instead. It only wraps the windows the radar already uses:
   an expired opportunity reads as its summary, anything else as the profile.
   Read-only, because accept/pass/chat belong to the signal that surfaced the
   card and a deep link does not say which signal that was. */

// ─── apps/mac/src/ui/mainview/windows.jsx ─────────────────────────────────────
function DeepLinkWindow({ person, route, onClose }) {
  const expired = route === "card" && person.status === "expired";
  return (
    <div
      onClick={onClose}
      style={{
        position:"fixed", inset:0, zIndex:900,
        display:"flex", alignItems:"center", justifyContent:"center",
        padding:"56px 18px",
      }}>
      <div
        onClick={(e) => e.stopPropagation()}
        style={{ display:"flex", width:"min(460px, 100%)", maxHeight:"100%", minHeight:0 }}>
        {expired
          ? <SummaryWindow person={person} onClose={onClose}/>
          : <ProfileWindow person={person} onClose={onClose} actions={false}/>}
      </div>
    </div>
  );
}

/* A conversation opened from an OS notification.

   The chat normally lives as a third column inside the signal that surfaced
   the match, so opening it that way means switching signals — throwing away
   whatever the person was already looking at. A notification is an
   interruption, not a navigation, so it floats over the current screen
   instead and talks to the same conversation endpoints the column uses. */
function DeepLinkChatWindow({ person, conversationId, onClose }) {
  const [messages, setMessages] = useState([]);
  const [draft, setDraft] = useState("");
  const myId = (window.INDEX_DATA && window.INDEX_DATA.ME && window.INDEX_DATA.ME.id) || null;

  useEffect(() => {
    if (!window.IndexApp || !window.IndexApp.isAuthed()) return;
    const client = window.IndexApp.getClient();
    if (!client) return;
    let cancelled = false;
    client.conversations.messages(conversationId)
      .then((res) => {
        if (cancelled) return;
        setMessages(window.IndexApp.normalizeList(res, "messages").map((m) => apiChatMessage(m, myId)));
      })
      .catch(() => {});
    // The thread stays live while it floats: the notification that opened it
    // may well be followed by another line before it is closed.
    const sub = window.IndexApp.streamInbox((event) => {
      if (!event || event.type !== "message" || !event.message) return;
      if (event.conversationId !== conversationId) return;
      const m = apiChatMessage(event.message, myId);
      if (m.who === "you") return;   // our own sends are already on screen
      setMessages((prev) => prev.some((x) => x.id === m.id) ? prev : [...prev, m]);
    });
    return () => { cancelled = true; if (sub && sub.close) sub.close(); };
  }, [conversationId, myId]);

  const send = () => {
    const text = draft.trim();
    if (!text) return;
    setDraft("");
    setMessages((prev) => [...prev, { id: rid(), who:"you", text, at: nowISO() }]);
    const client = window.IndexApp && window.IndexApp.getClient();
    if (client) client.conversations.sendMessage(conversationId, { parts: [{ text }] }).catch(() => {});
  };

  return (
    <div
      onClick={onClose}
      style={{
        position:"fixed", inset:0, zIndex:900,
        display:"flex", alignItems:"center", justifyContent:"center",
        padding:"56px 18px",
      }}>
      <div
        onClick={(e) => e.stopPropagation()}
        style={{ display:"flex", width:"min(460px, 100%)", maxHeight:"100%", minHeight:0 }}>
        <ChatWindow
          person={person}
          messages={messages}
          draft={draft}
          setDraft={setDraft}
          onSend={send}
          onClose={onClose}
        />
      </div>
    </div>
  );
}

/* Full profile for a person, opens in the 3rd window when you click their
   name or avatar on the radar. `actions` off drops the stage CTA, for a
   profile opened outside a signal (see DeepLinkWindow) where accepting or
   passing has no scope to act in. */
function ProfileWindow({ person, onClose, onAccept, onPass, onOpenChat, actions = true }) {
  const status = person.status;
  const isReady = status === "ready";
  const isAccepted = status === "accepted";
  const isExpired = status === "expired";
  // The intro someone wrote in their profile settings does not travel on an
  // opportunity card, so it is fetched here from GET /users/:id and merged
  // under anything the card already carried.
  const [fetched, setFetched] = useState(null);
  useEffect(() => {
    setFetched(null);
    const userId = person.userId;
    if (!userId || !window.IndexApp || !window.IndexApp.isAuthed()) return;
    const client = window.IndexApp.getClient();
    if (!client || !client.users || !client.users.get) return;
    let cancelled = false;
    client.users.get(userId)
      .then((res) => {
        if (cancelled) return;
        const u = (res && res.user) || res;
        if (u) setFetched(window.IndexApi.mapCounterpartProfile(u));
      })
      .catch(() => {});
    return () => { cancelled = true; };
  }, [person.userId]);

  const merged = fetched
    ? {
        ...person,
        bio: person.bio || fetched.bio,
        photo: person.photo || fetched.photo,
        socials: (person.socials && person.socials.length) ? person.socials : fetched.socials,
      }
    : person;
  const { bio, note, socials, meta } = profileContent(merged);
  return (
    <MacWindow title="profile" onClose={onClose} dismiss style={{ minHeight:0 }}>
      <div style={{ display:"grid", gridTemplateRows:"auto 1fr auto", gridTemplateColumns:"minmax(0, 1fr)", flex:1, minHeight:0, minWidth:0 }}>
        {/* header, just who this is. the stage they're at is already said by
            the footer (accept/pass vs send message), and a match percentage is
            the agent grading a person at you */}
        <div style={{
          padding:"14px 16px", borderBottom:"1px solid #000",
          display:"flex", gap:12, alignItems:"center", background:"#fff",
        }}>
          <Avatar id={person.userId || person.id} name={person.name} photo={merged.photo} size={42} ring={isAccepted}/>
          <div style={{
            fontFamily:"var(--amiga-title)", fontSize:17, fontWeight:600, color:"#000",
            minWidth:0, whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis",
          }}>{person.name}</div>
        </div>

        {/* body: their intro, then the presenter mainText (why surfaced), then
            where else to find them. */}
        <div className="mac-scroll" style={{
          overflowY:"auto", padding:"16px", display:"grid", gridTemplateColumns:"minmax(0, 1fr)", gap:15,
          alignContent:"start", background:"#fff",
        }}>
          {bio && (
            <SummarySection label="bio">
              <div style={{ display:"grid", gap:9 }}>
                {bio.split(/\n{2,}/).map((para, i) => (
                  <div key={i}>{para.trim()}</div>
                ))}
              </div>
            </SummarySection>
          )}

          {note && (
            <SummarySection label="why your agent surfaced them">
              <div style={{ display:"grid", gap:9 }}>
                {note.split(/\n{2,}/).map((para, i) => (
                  <div key={i}>{para.trim()}</div>
                ))}
              </div>
            </SummarySection>
          )}

          {socials.length > 0 && (
            <SummarySection label="elsewhere">
              <div style={{ display:"flex", flexWrap:"wrap", gap:6 }}>
                {socials.map(s => <SocialLink key={`${s.id}${s.handle}`} social={s}/>)}
              </div>
            </SummarySection>
          )}

          {isExpired && (
            <SummarySection label="why it closed">{expiryReason(person)}</SummarySection>
          )}

          {/* the leftovers, one quiet line, not four bullets under a heading */}
          {meta.length > 0 && (
            <div style={{
              fontFamily:"var(--mac-mono)", fontSize:10.5, color:"var(--ink-3)",
              letterSpacing:0.3, lineHeight:1.6,
            }}>{meta.join("  ·  ")}</div>
          )}
        </div>

        {/* footer CTA, matches the radar stage */}
        {actions && (
        <div style={{
          borderTop:"1px solid #000", padding:"10px 14px", background:"#fff",
          display:"flex", alignItems:"center", gap:10,
        }}>
          {isReady ? (
            <div style={{ display:"flex", gap:8, alignItems:"center" }}>
              <button className="amiga-gadget primary"
                onClick={() => onAccept && onAccept(person.id)}
                style={{ fontFamily:"var(--mac-mono)", fontSize:11, padding:"4px 14px" }}>accept</button>
              <button className="amiga-gadget"
                onClick={() => onPass && onPass(person.id)}
                style={{ fontFamily:"var(--mac-mono)", fontSize:11, padding:"4px 14px" }}>pass</button>
            </div>
          ) : isAccepted ? (
            <button className="amiga-gadget primary"
              onClick={() => onOpenChat && onOpenChat(person.id)}
              style={{ fontFamily:"var(--mac-mono)", fontSize:11, padding:"4px 14px" }}>send message</button>
          ) : isExpired ? (
            <span style={{ fontFamily:"var(--mac-mono)", fontSize:11, color:"var(--ink-3)" }}>this signal closed.</span>
          ) : (
            <span style={{ fontFamily:"var(--mac-mono)", fontSize:11, color:"var(--ink-3)" }}>
              answer their question in your feed to move forward.
            </span>
          )}
        </div>
        )}
      </div>
    </MacWindow>
  );
}

/* One API message in the shape the bubbles read. `at` is what a bubble reveals
   on hover; older rows have none and simply show nothing. */
function apiChatMessage(m, myId) {
  const parts = Array.isArray(m.parts) ? m.parts : [];
  const text = parts.map((p) => (p && typeof p === "object" && p.text) ? p.text : "")
    .filter(Boolean).join("\n");
  const who = m.senderId && myId && m.senderId === myId ? "you"
    : m.role === "agent" ? "index" : "them";
  return { id: m.id || rid(), who, text, at: m.createdAt || m.created_at || null };
}

function ChatWindow({ person, messages, draft, setDraft, onSend, onClose }) {
  const scrollRef = useRef(null);
  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages.length]);
  return (
    <MacWindow title="chat" onClose={onClose} dismiss style={{ minHeight:0 }}>
        <div style={{
          display:"grid",
          gridTemplateRows: "auto 1fr auto",
          gridTemplateColumns: "minmax(0, 1fr)",
          flex:1, minHeight:0, minWidth:0,
        }}>
          {/* header */}
          <div style={{
            padding:"12px 16px", borderBottom:"1px solid #000",
            display:"flex", gap:12, alignItems:"center", background:"#fff",
          }}>
            <Avatar id={person.userId || person.id} name={person.name} photo={person.photo} size={34}/>
            <div style={{ display:"grid", gap:2, minWidth:0 }}>
              <div style={{ fontFamily:"var(--amiga-title)", fontSize:15, fontWeight:600, color:"#000" }}>
                {person.name}
              </div>
              {person.location && (
                <div style={{ fontFamily:"var(--mac-mono)", fontSize:10, color:"var(--ink-2)" }}>
                  {person.location}
                </div>
              )}
            </div>
          </div>

          {/* messages */}
          <div ref={scrollRef} className="mac-scroll" style={{
            overflowY:"auto", padding:"14px 16px",
            display:"flex", flexDirection:"column", gap:10, background:"#fff",
          }}>
            <ChatOpener person={person}/>
            {messages.map(m => <ChatBubble key={m.id} m={m}/>)}
          </div>

          {/* input */}
          <div style={{ borderTop:"1px solid #000", background:"#fff" }}>
            <div style={{ padding:"7px 12px 8px", display:"flex", gap:10, alignItems:"center" }}>
              <span style={{ fontFamily:"var(--mac-mono)", color:"#000" }}>›</span>
              <input
                value={draft}
                onChange={e => setDraft(e.target.value)}
                onKeyDown={e => { if (e.key === "Enter") onSend(); }}
                placeholder={`message ${person.name}…`}
                style={{
                  flex:1, background:"transparent", border:"none", outline:"none",
                  color:"#000", fontFamily:"var(--mac-sans)", fontSize:13, padding:"4px 0",
                }}
              />
              <button className="amiga-gadget" onClick={onSend} style={{ padding:"3px 12px" }}>send</button>
            </div>
          </div>
        </div>
    </MacWindow>
  );
}

/* The whole opportunity, at the top of the thread: what it is, and what these
   two can do for each other. Without it the chat opens as a blank page
   addressed to a stranger, and the one-line headline was too thin to act on.
   It scrolls away with the log, because it is the first thing said rather than
   part of the chrome.

   The card's long write-up carries the substance; the headline sits above it
   when it says something the write-up does not already open with. */
function ChatOpener({ person }) {
  const headline = String(person.blurb || "").trim();
  const detail = String(person.detail || person.pitchFromAgent || "").trim();
  const body = detail || headline;
  if (!body) return null;
  const showHeadline = headline && normText(headline) !== normText(body);
  return (
    <div style={{
      border:"1px solid var(--ink-4)", background:"#FBFAF7",
      padding:"12px 14px", display:"grid", gap:7, marginBottom:6,
    }}>
      {showHeadline && (
        <span style={{
          fontFamily:"var(--mac-sans)", fontSize:13.5, fontWeight:600,
          color:"#000", lineHeight:1.35, letterSpacing:-0.1,
        }}>{headline}</span>
      )}
      <span style={{
        fontFamily:"var(--mac-sans)", fontSize:13, lineHeight:1.5, color:"var(--ink-2)",
      }}>{body}</span>
    </div>
  );
}

// The send time rides alongside the bubble and only surfaces while the row is
// hovered (or focused, for keyboard), so a thread reads as text until you go
// looking for when something was said. It stays in flow at zero opacity rather
// than appearing on hover, so nothing shifts under the pointer.
function ChatTime({ at }) {
  const text = chatTime(at);
  if (!text) return null;
  return (
    <time className="mac-chat-time" dateTime={at} style={{
      fontFamily:"var(--mac-mono)", fontSize:9, color:"var(--ink-3)",
      letterSpacing:0.2, whiteSpace:"nowrap", flex:"0 0 auto",
    }}>{text}</time>
  );
}

function ChatBubble({ m }) {
  if (m.who === "index") {
    return (
      <div className="mac-chat-row" style={{
        display:"flex", alignItems:"baseline", justifyContent:"center", gap:6, padding:"0 8px",
      }}>
        <div style={{
          fontFamily:"var(--mac-mono)", fontSize:10, color:"var(--ink-2)",
          textAlign:"center", letterSpacing:0.3, lineHeight:1.5,
        }}>{m.text}</div>
        <ChatTime at={m.at}/>
      </div>
    );
  }
  const you = m.who === "you";
  // Baseline, not flex-end: the time then sits on the bubble's first text line
  // instead of sagging to the bottom of the box, so it reads as part of the
  // message rather than as something floating beside it.
  return (
    <div className="mac-chat-row" style={{
      display:"flex", alignItems:"baseline", gap:6,
      justifyContent: you ? "flex-end" : "flex-start",
    }}>
      {you && <ChatTime at={m.at}/>}
      <div style={{
        maxWidth:"82%",
        border:"1px solid #000",
        background: you ? "#000" : "#fff",
        color:      you ? "#fff" : "#000",
        padding:"8px 11px",
        fontFamily:"var(--mac-sans)", fontSize:13, lineHeight:1.4,
        boxShadow: you ? "none" : "inset 1px 1px 0 #fff, inset -1px -1px 0 var(--ink-3)",
      }}>{m.text}</div>
      {!you && <ChatTime at={m.at}/>}
    </div>
  );
}

function ScoreBarBW({ value, inv }) {
  const pct = Math.max(0, Math.min(1, value));
  return (
    <div style={{
      width: 64, height: 7,
      border: `1px solid ${inv ? "#fff" : "#000"}`,
      background:"transparent",
      position:"relative", overflow:"hidden",
    }}>
      <div style={{
        width: `${pct*100}%`, height:"100%",
        backgroundImage: inv
          ? "repeating-linear-gradient(45deg, #fff 0, #fff 1px, #000 1px, #000 2px)"
          : "repeating-linear-gradient(45deg, #000 0, #000 1px, #fff 1px, #fff 2px)",
      }}/>
    </div>
  );
}

function StatusBadge({ status, inv }) {
  const map = {
    accepted:    "accepted",
    ready:       "ready · intro",
    negotiating: "negotiating",
    warm:        "discovered · warm",
    considering: "discovered",
    expired:     "expired",
    passed:      "passed",
  };
  const t = map[status] || "discovered";
  return (
    <span style={{
      fontFamily:"var(--mac-mono)", fontSize:10, letterSpacing:1,
      textTransform:"uppercase",
      color: inv ? "#000" : "#000",
      background: inv ? "#fff" : "#fff",
      border:`1px solid ${inv ? "#fff" : "#000"}`,
      padding:"1px 6px",
    }}>{t}</span>
  );
}

// ─── apps/mac/src/ui/mainview/core.jsx ────────────────────────────────────────
// Main view, Mac System 6 split-window layout with full flow logic
// Same simulation logic as the original; only chrome/skin is reworked.

// Width of the window row below which three side-by-side windows stop being
// readable, the radar steps aside for the third window instead.
const THREE_COLUMN_MIN = 1020;

// How long the radar describes discovery before accepting that a signal simply
// has not matched anyone yet. Long enough to cover a slow first pass, short
// enough that an empty radar stops pretending to be busy.
const DISCOVERY_GIVE_UP_MS = 120000;

function MainView({ profile, people, setPeople, conversation, setConversation,
                    field, setField, stats, simRate, setSimRate, tweaks = {},
                    onOpenRoom, onBack, registerChats, pendingFocus, onPendingHandled,
                    focusQuestion }) {
  // Live-only: these demo sim feeds no longer exist, so they default to empty.
  // The simulation loops below stay wired but idle on empty arrays.
  const { FIELD_EVENTS = [], AMBIENT_NOTES = [] } = window.INDEX_DATA;
  // "all" opens the radar on the whole field with no stage selected, so the
  // negotiating rows are visible next to the ones awaiting you and a status
  // changing under the agents can be watched as it happens. Selecting a stage
  // still filters; nothing starts filtered.
  const [tab, setTab] = useState("all");
  // Counterparty discovery is what the radar shows while it has nothing to show
  // yet: the window between a signal going live and the first counterparty
  // landing. Deliberately not tied to having just created the signal, because
  // reopening a young signal lands in exactly the same empty state and "no one
  // here right now" is the wrong thing to say while the agents are still out.
  const [discoveryMetrics, setDiscoveryMetrics] = useState({});
  // A signal can legitimately match nobody, so discovery is not allowed to spin
  // forever: past this it gives up and the ordinary empty state takes over.
  const [discoveryExpired, setDiscoveryExpired] = useState(false);
  const [paused, setPaused] = useState(() => profile.status === "paused");
  const [pipelineMode, setPipelineMode] = useState("broad");
  const modeTimerRef = useRef(null);

  // ---- live backend wiring ------------------------------------------------
  // When signed in and this signal maps to a real intent, the radar, agent
  // chat, and H2H threads come from services/api; otherwise the simulation
  // below runs as the signed-out (browser preview) demo. The polling loop,
  // handlers, and inbox stream that consume these live below.
  const intentId = profile.intentId || null;
  const live = !!(window.IndexApp && window.IndexApp.isAuthed() && intentId);
  // Memoize the client so the polling/inbox effects don't reset every render
  // (getClient() returns a fresh object each call). The key is read lazily.
  const client = useMemo(
    () => (live && window.IndexApp.getClient ? window.IndexApp.getClient() : null),
    [live],
  );
  // Latest intent id for in-flight poll checks (closure intentId is fixed per call).
  const intentIdRef = useRef(intentId);
  intentIdRef.current = intentId;
  // Current user id (for telling "you" from "them" in H2H threads). Mirrored
  // onto INDEX_DATA.ME by app.jsx after the snapshot loads.
  const myId = (window.INDEX_DATA && window.INDEX_DATA.ME && window.INDEX_DATA.ME.id) || null;
  const { patchIntentStatus, refreshIntents } = useIndexEnv();
  const radarSeqRef = useRef(0);               // drops stale radar responses
  const convByPerson = useRef({});             // opportunityId -> conversationId
  const personByConv = useRef({});             // conversationId -> opportunityId

  const flashMode = (m, holdMs = 9000) => {
    setPipelineMode(m);
    if (modeTimerRef.current) clearTimeout(modeTimerRef.current);
    modeTimerRef.current = setTimeout(() => {
      if (m === "narrowing") setPipelineMode("focused");
      else setPipelineMode("broad");
    }, holdMs);
  };
  useEffect(() => () => modeTimerRef.current && clearTimeout(modeTimerRef.current), []);

  /* ----- ambient sim: append field events + maybe bump scores (demo only) ----- */
  useInterval(() => {
    if (paused || !FIELD_EVENTS.length) return;
    const ev = FIELD_EVENTS[Math.floor(Math.random() * FIELD_EVENTS.length)];
    setField(prev => [{ ...ev, id: Math.random().toString(36).slice(2), t: now() }, ...prev].slice(0, 50));
    if (Math.random() < 0.4) {
      setPeople(prev => {
        const visible = prev.filter(p => !p.hidden);
        if (visible.length === 0) return prev;
        const idx = prev.indexOf(visible[Math.floor(Math.random() * visible.length)]);
        const p = prev[idx];
        const next = [...prev];
        const delta = (Math.random() - 0.3) * 0.04;
        next[idx] = { ...p, score: Math.min(0.99, Math.max(0.4, p.score + delta)) };
        return next;
      });
    }
  }, (paused || live) ? null : Math.max(800, 4200 / simRate));

  const pushAmbientNote = () => {
    if (!AMBIENT_NOTES.length) return;
    const n = AMBIENT_NOTES[Math.floor(Math.random() * AMBIENT_NOTES.length)];
    setConversation(prev => [
      ...prev,
      { kind:"note", id: Math.random().toString(36).slice(2), text: n, t: now() },
    ]);
  };

  // Ambient chatter disabled, the feed shows only questions + your responses.
  useInterval(() => {}, null);

  /* ----- ambient pipeline breathing ----- */
  useInterval(() => {
    if (paused) return;
    const choice = Math.random();
    if (choice < 0.55) {
      const surfaceCount = Math.random() < 0.3 ? 2 : 1;
      setPeople(prev => {
        const next = [...prev];
        for (let n = 0; n < surfaceCount; n++) {
          const hiddenIdxs = next.map((p, i) => p.hidden ? i : -1).filter(i => i >= 0);
          if (hiddenIdxs.length === 0) break;
          const j = hiddenIdxs[Math.floor(Math.random() * hiddenIdxs.length)];
          next[j] = { ...next[j], hidden: false };
        }
        return next;
      });
      flashMode("expanding", 5000);
      const lines = [
        "field widened · a new candidate just walked in.",
        "ambient discovery · agent caught a new signal nearby.",
        "someone new just got an agent online · indexing.",
        "passing-by candidate just opted into the field.",
      ];
      setField(prev => [{
        kind:"warm", text: lines[Math.floor(Math.random()*lines.length)],
        id: Math.random().toString(36).slice(2), t: now(),
      }, ...prev].slice(0, 50));
    } else if (choice < 0.7) {
      flashMode("narrowing", 5000);
    } else {
      setPeople(prev => {
        const stale = prev.filter(p => !p.hidden && (p.status === "considering" || p.status === "warm") && p.score < 0.72);
        if (stale.length === 0) return prev;
        stale.sort((a, b) => a.score - b.score);
        const victim = stale[0];
        const idx = prev.indexOf(victim);
        const next = [...prev];
        next[idx] = { ...victim, status: "expired" };
        return next;
      });
      setField(prev => [{
        kind:"passed", text:"a candidate just expired · they left or the moment closed.",
        id: Math.random().toString(36).slice(2), t: now(),
      }, ...prev].slice(0, 50));
    }
  }, (paused || live) ? null : 14000 / simRate);

  /* ----- live radar polling ----- */
  // Intent switches keep MainView mounted; wipe the previous signal's radar
  // before the next poll lands.
  useEffect(() => {
    if (!live) return;
    radarSeqRef.current += 1;
    setPeople([]);
  }, [live, intentId, setPeople]);

  const refreshRadar = React.useCallback(async () => {
    if (!live || !client || !intentId) return;
    const seq = ++radarSeqRef.current;
    const forIntent = intentId;
    // Intent radar asks for the full lifecycle (like the web app's RADAR_STATUSES),
    // otherwise the home endpoint only returns actionable rows and the
    // accepted/missed tabs stay empty. `rejected` is deliberately excluded:
    // most rejections are agent-side filtering, not user decisions, so
    // showing them implies choices the user never made.
    const radarStatuses = "pending,negotiating,accepted,expired";
    const applyRadar = (radarR) => {
      if (!radarR) return;
      const items = window.IndexApp.normalizeList(radarR, "items");
      const mapped = window.IndexApi.mapPeopleFromRadarItems(items).map((p) => ({
        // The radar is intent-scoped, so stamping the signal onto each person
        // lets a deep link know which signal already owns the one it names.
        ...p, intentId: forIntent, hidden: false,
        score: typeof p.score === "number" ? p.score : 0.7,
      }));
      const apply = window.IndexApi.applyRadarPeople || ((prev, next) => next);
      setPeople((prev) => apply(prev, mapped));
      setDiscoveryMetrics((prev) => ({
        ...prev,
        found: items.length,
        scored: items.filter((it) => typeof (it && it.score) === "number").length,
        advanced: mapped.filter((p) => opportunityBucket(p) !== null).length,
      }));
    };

    const skeletonR = await client.opportunities
      .radarForIntent(forIntent, { statuses: radarStatuses, presentation: "skeleton" })
      .catch(() => null);
    if (radarSeqRef.current !== seq || intentIdRef.current !== forIntent) return;
    applyRadar(skeletonR);

    const radarR = await client.opportunities
      .radarForIntent(forIntent, { statuses: radarStatuses })
      .catch(() => null);
    if (radarSeqRef.current !== seq || intentIdRef.current !== forIntent) return;
    applyRadar(radarR);
  }, [live, client, intentId, setPeople]);

  const visiblePeople = useMemo(() => people.filter(p => !p.hidden), [people]);
  // What the radar actually lists, which is what "empty" has to mean here: a
  // person filtered out of every stage is not something the user can see.
  const shownPeople = useMemo(
    () => visiblePeople.filter(p => opportunityBucket(p) !== null),
    [visiblePeople]
  );
  const filtered = useMemo(() => [...visiblePeople].sort((a, b) => b.score - a.score), [visiblePeople]);

  // People you're still in negotiation with, anyone not yet ready/accepted/gone.
  const negotiatingPeople = useMemo(
    () => visiblePeople.filter(p => !["accepted", "ready", "expired", "passed"].includes(p.status)),
    [visiblePeople]
  );
  // Nothing on the radar and not yet given up: the agents are still out.
  const discovering = live && shownPeople.length === 0 && !discoveryExpired;

  // The clock starts per signal, and a signal that lands someone stops it for
  // good: the give-up state only exists for the empty case.
  useEffect(() => {
    setDiscoveryExpired(false);
    setDiscoveryMetrics({});
  }, [intentId]);

  useEffect(() => {
    if (!live || shownPeople.length > 0) return;
    const t = setTimeout(() => setDiscoveryExpired(true), DISCOVERY_GIVE_UP_MS);
    return () => clearTimeout(t);
  }, [live, shownPeople.length]);

  // Reach is the one stage number that does not come from the radar, so it is
  // asked for once while discovery is on screen.
  useEffect(() => {
    if (!live || !client || !discovering) return;
    let alive = true;
    client.networks.list()
      .then((r) => {
        if (!alive) return;
        const networks = window.IndexApp.normalizeList(r, "networks");
        setDiscoveryMetrics((prev) => ({ ...prev, networks: networks.length }));
      })
      .catch(() => { /* the line stays unlit rather than showing a guess */ });
    return () => { alive = false; };
  }, [live, client, discovering]);

  useEffect(() => {
    if (!live) return;
    refreshRadar();
    const t = setInterval(refreshRadar, 5000);
    return () => clearInterval(t);
  }, [live, refreshRadar]);

  /* ----- the signal inbox: transcript, pending questions, owner writes ----- */
  // GET /conversations/agent/messages?intentId= is the H2A inbox. Questions
  // from a responder are `agent.questions`; the owner's own words are just
  // messages. Same poll the web app runs.
  const [agentMessages, setAgentMessages] = useState([]);
  const [agentQuestions, setAgentQuestions] = useState([]);
  const refreshInbox = React.useCallback(() => {
    if (!live || !client || !intentId) return Promise.resolve();
    const forIntent = intentId;
    return client.conversations.messages("agent", { intentId: forIntent })
      .then((res) => {
        if (intentIdRef.current !== forIntent) return;
        const questions = (res && res.agent && res.agent.questions) || [];
        setAgentQuestions(questions);
        const carded = {};
        questions.forEach((q) => { if (q && q.id) carded[q.id] = true; });
        setAgentMessages(window.IndexApp.normalizeList(res, "messages").map((m) => {
          const text = ((m && m.parts) || [])
            .filter((p) => p && typeof p.text === "string")
            .map((p) => p.text).join("\n").trim();
          const provenance = (m.metadata && m.metadata.principalMessage) || {};
          if (!text) return null;
          if (provenance.kind === "question" && provenance.questionId && carded[provenance.questionId]) return null;
          return {
            id: m.id,
            kind: m.role === "user" ? "user" : "agent",
            text,
            scope: provenance.scope,
            matches: provenance.matches,
          };
        }).filter(Boolean));
      })
      .catch(() => {});
  }, [live, client, intentId]);
  useEffect(() => {
    setAgentMessages([]);
    setAgentQuestions([]);
    if (!live || !client) return;
    refreshInbox();
    const t = setInterval(refreshInbox, 5000);
    return () => clearInterval(t);
  }, [live, client, refreshInbox]);

  // The app's one /events connection already carries this signal's H2A: a new
  // agent message arrives as `message` tagged with the intent, a new question
  // as `question.pending`. Read on either so the inbox is live; the poll above
  // stays as the backstop, since the native stream does not resume by event id.
  useEffect(() => {
    if (!live || !client || !intentId || !window.IndexApp) return;
    const sub = window.IndexApp.streamInbox((event) => {
      if (!event) return;
      const forIntent = event.type === "message"
        ? event.message && event.message.metadata && event.message.metadata.intentId
        : event.type === "question.pending" && event.data && event.data.intentId;
      if (forIntent !== intentId) return;
      refreshInbox();
    });
    return () => { if (sub && sub.close) sub.close(); };
  }, [live, client, intentId, refreshInbox]);

  const sendAgentMessage = (text, onDone) => {
    if (!client || !intentId || !text) return;
    client.conversations.sendMessage("agent", {
      parts: [{ kind: "text", text }],
      metadata: { intentId },
    }).then(() => refreshInbox()).finally(() => onDone && onDone());
  };

  const sendAgentAnswers = (answers, onDone) => {
    if (!client || !intentId || !answers.length) return;
    client.conversations.sendAnswers(intentId, answers)
      .then(() => refreshInbox()).finally(() => onDone && onDone());
  };

  // The four states an opportunity can be in for you, in the order they happen:
  // it needs you, agents are still talking, you took it, it ran out.
  // "awaiting you" leads because it is the only one you can act on.
  // Rejected/passed people are not shown: those are mostly agent-side
  // filtering decisions, and listing them reads as if the user (or the
  // other person) did the rejecting.
  const funnelStages = useMemo(() => {
    const by = (s) => visiblePeople.filter(p => opportunityBucket(p) === s).length;
    return [
      { label:"awaiting you", count: by("awaiting you"), accent:true },
      { label:"negotiating",  count: by("negotiating") },
      { label:"accepted",     count: by("accepted"), accent:true },
      { label:"missed",       count: by("missed") },
    ];
  }, [visiblePeople]);

  /* ----- chat (3rd window): opens when you click someone in the pipeline ----- */
  const [chatId, setChatId] = useState(null);
  const chatIdRef = useRef(null);
  useEffect(() => { chatIdRef.current = chatId; }, [chatId]);
  const [chats, setChats] = useState({});
  const [chatDraft, setChatDraft] = useState("");
  const [unread, setUnread] = useState({});   // personId -> unread count
  const [responses, setResponses] = useState({});      // your typed answer to each person's question
  const [summaryId, setSummaryId] = useState(null);    // expired person whose summary is open
  const [profileId, setProfileId] = useState(null);    // person whose profile is open

  const toChatMsg = (m) => apiChatMessage(m, myId);

  const openChat = (personId) => {
    setChatId(personId);
    setSummaryId(null);
    setProfileId(null);
    setUnread(prev => (prev[personId] ? { ...prev, [personId]: 0 } : prev));

    if (live && client) {
      client.opportunities.startChatForIntent(personId, intentId)
        .then((res) => {
          const cid = res && res.conversationId;
          if (!cid) return;
          convByPerson.current[personId] = cid;
          personByConv.current[cid] = personId;
          return client.conversations.messages(cid).then((msgsRes) => {
            const msgs = window.IndexApp.normalizeList(msgsRes, "messages").map(toChatMsg);
            setChats(prev => ({ ...prev, [personId]: msgs }));
          });
        })
        .catch(() => {});
      return;
    }

    setChats(prev => {
      if (prev[personId]) return prev;
      const person = people.find(p => p.id === personId);
      return person ? { ...prev, [personId]: seedChat(person, responses[personId]) } : prev;
    });
  };
  const openSummary = (personId) => { setSummaryId(personId); setChatId(null); setProfileId(null); };
  const openProfile = (personId) => { setProfileId(personId); setChatId(null); setSummaryId(null); };
  const closeChats = () => { setChatId(null); setSummaryId(null); setProfileId(null); };

  // Negotiating people are waiting on a response to their question. Responding
  // clears the negotiation and makes them ready, that's when the opportunity
  // to accept appears. Accepting (only available once ready) opens the chat.
  const respondPerson = (personId, text) => {
    const person = people.find(p => p.id === personId);
    setPeople(prev => prev.map(p =>
      p.id === personId ? { ...p, status: "ready" } : p));
    if (text && text.trim()) {
      setResponses(prev => ({ ...prev, [personId]: text.trim() }));
    }
    // Leave a quiet record so the answered question rises into the scrollback
    // instead of just vanishing. Collective answers (one question, many people)
    // dedupe so they only post once.
    if (person) {
      const q = personQuestion(person);
      setConversation(prev => {
        const last = prev[prev.length - 1];
        if (last && last.kind === "clarifier" && last.answered && last.text === q) return prev;
        return [...prev, {
          kind: "clarifier", answered: true,
          id: "pq-" + personId + "-" + prev.length,
          text: q,
          choice: (text && text.trim()) ? text.trim() : "answered",
          source: "person",
          sourceMeta: { name: person.name },
        }];
      });
    }
  };
  // Accepting means "I want to talk to this person", so go straight into the
  // chat instead of letting the card silently jump to the accepted tab. Match
  // the web (useOpportunityActions): in live mode the card only moves to
  // "accepted" once the server confirms, so a failed accept can't leave a
  // phantom in the accepted tab. On failure, refresh from the server so the
  // radar reflects the real state instead of the optimistic one.
  const acceptPerson = (personId) => {
    if (live && client) {
      client.opportunities.updateStatusForIntent(personId, "accepted", intentId)
        .then(() => {
          setPeople(prev => prev.map(p =>
            p.id === personId ? { ...p, status: "accepted" } : p));
          openChat(personId);
          setTimeout(refreshRadar, 1500);
        })
        .catch(() => refreshRadar());
      return;
    }
    setPeople(prev => prev.map(p =>
      p.id === personId ? { ...p, status: "accepted" } : p));
    openChat(personId);
  };
  // Pass is the other half of the ready-stage decision, decline the intro
  // instead of accepting it. They drop out of the radar into "passed". Like
  // accept, only commit the local status once the server confirms so a failed
  // reject can't hide a still-pending opportunity; refresh on failure.
  const passPerson = (personId) => {
    if (chatId === personId) closeChats();
    if (live && client) {
      client.opportunities.updateStatusForIntent(personId, "rejected", intentId)
        .then(() => {
          setPeople(prev => prev.map(p =>
            p.id === personId ? { ...p, status: "passed" } : p));
          setTimeout(refreshRadar, 1500);
        })
        .catch(() => refreshRadar());
      return;
    }
    setPeople(prev => prev.map(p =>
      p.id === personId ? { ...p, status: "passed" } : p));
  };
  const sendChat = () => {
    const text = chatDraft.trim();
    if (!text || !chatId) return;
    const id = chatId;
    setChatDraft("");
    setChats(prev => ({ ...prev, [id]: [...(prev[id] || []), { id: rid(), who:"you", text, at: nowISO() }] }));

    if (live && client) {
      const cid = convByPerson.current[id];
      if (cid) client.conversations.sendMessage(cid, { parts: [{ text }] }).catch(() => {});
      return;
    }

    setTimeout(() => {
      setChats(prev => ({ ...prev, [id]: [...(prev[id] || []), { id: rid(), who:"them", text: chatReplyFor(text), at: nowISO() }] }));
    }, 700);
  };

  // Agents you've already talked to occasionally ping you. If their chat isn't
  // the one you're looking at, it just bumps a quiet unread marker, no popups.
  useInterval(() => {
    if (paused) return;
    const candidates = Object.keys(chats).filter(id => id !== chatId);
    if (candidates.length === 0) return;
    const pid = candidates[Math.floor(Math.random() * candidates.length)];
    const person = people.find(p => p.id === pid);
    setChats(prev => ({ ...prev, [pid]: [...(prev[pid] || []), { id: rid(), who:"them", text: incomingPing(person), at: nowISO() }] }));
    setUnread(prev => ({ ...prev, [pid]: (prev[pid] || 0) + 1 }));
  }, (paused || live || Object.keys(chats).length === 0) ? null : 16000 / simRate);

  // Live inbox, append counterpart/agent messages to any open H2H thread.
  useEffect(() => {
    if (!live || !window.IndexApp) return;
    const sub = window.IndexApp.streamInbox((event) => {
      if (!event || event.type !== "message" || !event.message) return;
      const pid = personByConv.current[event.conversationId];
      if (!pid) return;
      const m = toChatMsg(event.message);
      if (m.who === "you") return; // don't echo our own optimistic sends
      setChats(prev => {
        const list = prev[pid] || [];
        if (list.some((x) => x.id === m.id)) return prev;
        return { ...prev, [pid]: [...list, m] };
      });
      setUnread(prev => (pid === chatIdRef.current ? prev : { ...prev, [pid]: (prev[pid] || 0) + 1 }));
    });
    return () => { if (sub && sub.close) sub.close(); };
  }, [live]);

  // Pause holds the signal: the agent stops taking on new work, but the
  // opportunities and questions it already surfaced stay put. On a live signal
  // that's a real status change, not just a local hold, revert if it doesn't
  // land so the button never claims something the backend didn't do. Also patch
  // the shared INTENTS snapshot so the hub shows paused/active without a reload.
  const togglePause = () => {
    const next = !paused;
    setPaused(next);
    if (live && client && intentId) {
      client.intents.updateStatus(intentId, next ? "PAUSED" : "ACTIVE")
        .then(() => {
          if (patchIntentStatus) patchIntentStatus(intentId, next ? "paused" : "active");
        })
        .catch(() => setPaused(!next));
    }
  };

  // Archive retires the signal and drops it off the hub. Only leave the screen
  // once the backend has taken it, otherwise you'd land back on a hub still
  // showing the signal you thought you'd just archived.
  const archiveSignal = () => {
    if (!(live && client && intentId)) { onBack && onBack(); return Promise.resolve(); }
    return client.intents.archive(intentId).then(async () => {
      if (patchIntentStatus) patchIntentStatus(intentId, "archived");
      if (refreshIntents) await refreshIntents().catch(() => null);
      onBack && onBack();
    });
  };

  // Three columns need room. Below that the third window takes the radar's
  // place rather than all three squeezing to the point where a card's name and
  // its accept/pass gadgets sit on top of each other; closing it brings the
  // radar back.
  const shellRef = useRef(null);
  const [narrow, setNarrow] = useState(false);
  useEffect(() => {
    const el = shellRef.current;
    if (!el || typeof ResizeObserver === "undefined") return;
    const ro = new ResizeObserver((entries) => {
      const w = entries[0] && entries[0].contentRect.width;
      if (w) setNarrow(w < THREE_COLUMN_MIN);
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  const chatPerson = chatId ? people.find(p => p.id === chatId) : null;
  const summaryPerson = summaryId ? people.find(p => p.id === summaryId) : null;
  const profilePerson = profileId ? people.find(p => p.id === profileId) : null;
  const thirdOpen = !!(chatPerson || summaryPerson || profilePerson);
  const showRadar = !(thirdOpen && narrow);
  const chatIds = Object.keys(chats);
  const unreadTotal = chatIds.reduce((a, id) => a + (unread[id] || 0), 0);
  const roster = chatIds.map(id => {
    const p = people.find(x => x.id === id);
    return { id, name: p ? p.name : id, unread: unread[id] || 0, active: id === chatId };
  });
  const conversations = chatIds.map(id => {
    const p = people.find(x => x.id === id);
    const msgs = chats[id] || [];
    const last = msgs.length ? msgs[msgs.length - 1] : null;
    return {
      id, person: p, name: p ? p.name : id,
      unread: unread[id] || 0,
      last: last ? last.text : "",
      lastWho: last ? last.who : null,
    };
  }).sort((a, b) => b.unread - a.unread);

  // Publish this signal's chat list up to the top menubar (which groups by
  // signal). Keep openChat fresh via a ref; re-publish only when the list/unread
  // change (rosterKey). We don't clear on unmount, so the menu persists across
  // screens (works from the landing screen too).
  const openChatRef = useRef(openChat);
  openChatRef.current = openChat;
  const signalTitle = profile.intent || "your signal";
  const rosterKey = roster.map(r => `${r.id}:${r.unread}`).join("|");
  useEffect(() => {
    if (registerChats) registerChats(signalTitle, roster, (id) => openChatRef.current(id));
  }, [rosterKey, signalTitle]);

  // What the menubar or a deep link asked to open once this signal mounted.
  // A chat opens from the id alone, but a profile renders from the radar row,
  // which arrives a moment after the signal does — so hold the request until
  // that person lands rather than opening an empty panel.
  const focusedTabRef = useRef(null);
  useEffect(() => {
    if (!pendingFocus) return;
    if (pendingFocus.kind === "profile") {
      // The stage moves first and only once, so a person still loading is at
      // least filtered into view, and a tab picked in the meantime stands.
      if (focusedTabRef.current !== pendingFocus) {
        focusedTabRef.current = pendingFocus;
        const bucket = opportunityBucket(pendingFocus);
        if (bucket) setTab(bucket);
      }
      if (!people.some((p) => p.id === pendingFocus.personId)) return;
      openProfile(pendingFocus.personId);
    } else {
      openChat(pendingFocus.personId);
    }
    onPendingHandled && onPendingHandled();
  }, [pendingFocus, people]);

  return (
    <div style={{
      position:"absolute", inset:0,
      display:"grid",
      gridTemplateRows:"1fr",
      // deep top and bottom margins frame the windows on the desktop (and keep
      // the chrome well clear of the floating traffic lights); the sides stay
      // tight because the three columns want the width
      padding: "56px 18px 56px", gap: 8,
    }}>
      <div ref={shellRef} style={{
        display:"grid",
        // Opening a chat splits into a third column, the pipeline narrows to
        // make room rather than the chat floating on top.
        // The minimums are 0, not a px floor: a floor larger than the window
        // makes the tracks overflow the desktop and the last column runs off
        // the right edge. The windows clip their own content instead.
        gridTemplateColumns: (thirdOpen && showRadar)
          ? "minmax(0, 40fr) minmax(0, 30fr) minmax(0, 30fr)"
          : "minmax(0, 56fr) minmax(0, 44fr)",
        gridTemplateRows: "minmax(0, 1fr)",
        gap: 8, minHeight:0,
      }}>
        <MacWindow title="signal" onClose={onBack}>
          <ConversationPane
            profile={profile}
            conversation={conversation}
            negotiatingPeople={live ? [] : negotiatingPeople}
            onRespondPerson={respondPerson}
            agentMessages={live ? agentMessages : null}
            agentQuestions={live ? agentQuestions : []}
            onSendAgent={live ? sendAgentMessage : null}
            onSendAnswers={live ? sendAgentAnswers : null}
            focusQuestion={focusQuestion}
            paused={paused}
            onTogglePause={togglePause}
            onArchive={archiveSignal}
          />
        </MacWindow>

        {showRadar && (
        <MacWindow title="radar" onClose={onBack}>
          <MatchFeed
            tab={tab} setTab={setTab}
            profile={profile}
            people={filtered}
            allPeople={visiblePeople}
            field={field}
            funnelStages={funnelStages}
            pipelineMode={pipelineMode}
            onOpenRoom={openChat}
            onAccept={acceptPerson}
            onPass={passPerson}
            onSummary={openSummary}
            onProfile={openProfile}
            unread={unread}
            chatIds={chatIds}
            discovering={discovering}
            discoveryMetrics={discoveryMetrics}
          />
        </MacWindow>
        )}

        {thirdOpen && (
          chatPerson ? (
            <ChatWindow
              person={chatPerson}
              messages={chats[chatId] || []}
              draft={chatDraft}
              setDraft={setChatDraft}
              onSend={sendChat}
              onClose={closeChats}
            />
          ) : summaryPerson ? (
            <SummaryWindow person={summaryPerson} onClose={closeChats}/>
          ) : profilePerson ? (
            <ProfileWindow
              person={profilePerson}
              onClose={closeChats}
              onAccept={acceptPerson}
              onPass={passPerson}
              onOpenChat={openChat}
            />
          ) : null
        )}
      </div>
    </div>
  );
}

// ─── apps/mac/src/ui/mainview/exports.jsx ─────────────────────────────────────
function BottomBar({ stats }) {
  return (
    <div style={{
      border:"1px solid #000", background:"#fff",
      display:"grid", gridTemplateColumns:"1fr auto",
      alignItems:"center",
      padding:"0 14px", gap:14,
      fontFamily:"var(--mac-mono)", fontSize:10,
      color:"#000", height:"100%",
    }}>
      <div style={{ display:"flex", gap:18, alignItems:"center" }}>
        <span style={{ letterSpacing:1.5 }}>FIELD</span>
        <span><b>{stats.online}</b> agents online</span>
        <span>·</span>
        <span>inspected <b>{stats.inspected}</b></span>
        <span>·</span>
        <span>passed <b>{stats.passed}</b></span>
      </div>
      <div style={{ display:"flex", gap:12, alignItems:"center" }}>
        <LiveDot size={6}/>
        <span>syn-0518-bk-04</span>
      </div>
    </div>
  );
}

window.MainView = MainView;
window.DeepLinkWindow = DeepLinkWindow;
window.DeepLinkChatWindow = DeepLinkChatWindow;

// ─── apps/mac/src/ui/app.jsx ──────────────────────────────────────────────────
// App, orchestrates the Mac System 6 prototype against the live backend.
// Auth source of truth is a credential-free boolean surfaced by the native
// Keychain owner. Requests cross the structured native bridge. When signed out
// the app shows sign-in; INDEX_DATA is only a signed-out demo
// fallback for browser preview where the Swift bridge is absent.

// Live-only: there is no static demo data. window.INDEX_DATA starts empty and is
// filled with the signed-in user's ME/NETWORKS/INTENTS by applyLoaded once the
// snapshot loads; side screens (settings/networks) read that live mirror.
window.INDEX_DATA = window.INDEX_DATA || {};

// Live data (mapped snapshot + ME/NETWORKS) is threaded through this context so
// screens can read it; everything is empty until the snapshot loads.
const IndexDataContext = React.createContext(null);
function useIndexData() {
  const ctx = React.useContext(IndexDataContext);
  return (ctx && ctx.data) || window.INDEX_DATA;
}
function useIndexEnv() {
  return React.useContext(IndexDataContext) || {
    data: window.INDEX_DATA, me: null, networks: null, features: {}, live: false,
    refreshNetworks: () => {},
    refreshIntents: () => {},
    patchIntentStatus: () => {},
  };
}

function nativeAuthed() {
  return !!(window.IndexApp && window.IndexApp.isAuthed());
}

// Resolve a parsed deep link (see api/deeplink.mjs) to a person card. A card
// link carries an opportunity id, a profile link a user id, so each is looked
// up against the loaded radar first. Anything this snapshot does not carry
// gets one fetch by id through the existing client methods, and null when even
// that comes up empty, so the caller can say so instead of opening a blank
// window.
// A conversation link (minted by the app's own OS toasts) names a thread
// rather than a person card. Its provenance carries both the signal the thread
// belongs to and the opportunity behind it, so the caller can open that signal
// on the chat, and fall back to a floating chat with a name and face when the
// signal is no longer on the hub.
async function resolveDeepLinkConversation(route, people) {
  if (!nativeAuthed() || !window.IndexApp) return null;
  const client = window.IndexApp.getClient();
  if (!client) return null;
  try {
    const res = await client.conversations.list();
    const conv = window.IndexApp.normalizeList(res, "conversations").find((row) => row && row.id === route.id);
    const via = conv && Array.isArray(conv.via) ? conv.via[0] : null;
    if (!via) return null;
    const person = await resolveDeepLinkPerson({ route: "card", id: via.opportunityId }, people);
    return person
      ? { person, conversationId: route.id, intentId: via.intentId || null }
      : null;
  } catch (e) {
    return null;
  }
}

async function resolveDeepLinkPerson(route, people) {
  const known = route.route === "card"
    ? people.find(p => p.id === route.id)
    : people.find(p => p.userId === route.id);
  if (known) return known;

  if (!nativeAuthed() || !window.IndexApp) return null;
  const client = window.IndexApp.getClient();
  if (!client) return null;
  try {
    if (route.route === "card") {
      const res = await client.opportunities.get(route.id);
      const row = (res && res.opportunity) || res;
      if (!row || !row.id) return null;
      const person = window.IndexApi.mapPeopleFromOpportunities([row])[0] || null;
      // GET /opportunities/:id names the counterpart under otherParties rather
      // than the counterpartUserId/counterpartName the list mapper reads, and
      // the profile needs the user id to fetch their bio. `intentId` is the
      // viewer's own signal, which is what decides between opening that signal
      // and floating a card.
      const other = Array.isArray(row.otherParties) ? row.otherParties[0] : null;
      if (person) person.intentId = row.intentId || null;
      if (person && other) {
        person.userId = person.userId || other.id || null;
        person.name = other.name || person.name;
        person.photo = person.photo || other.avatar || null;
      }
      return person;
    }
    const res = await client.users.get(route.id);
    const user = (res && res.user) || res;
    if (!user || !user.id) return null;
    return {
      id: user.id,
      userId: user.id,
      name: user.name || "unknown",
      location: user.location || "",
      ...window.IndexApi.mapCounterpartProfile(user),
    };
  } catch (e) {
    return null;
  }
}

function App() {
  const [screen, setScreen] = useState(() => nativeAuthed() ? "building" : "login");
  // True until the user creates their first signal, the hub opens empty.
  const [freshUser, setFreshUser] = useState(false);
  const [profile, setProfile] = useState({});
  // First run, in order: the name confirmed on the card, then what the
  // public-research lookup made of it. Both feed the getting-started review.
  const [confirmedName, setConfirmedName] = useState("");
  const [enriched, setEnriched] = useState(null);
  // Live snapshot state; null until loadSnapshot() resolves (or in demo mode).
  const [snapshot, setSnapshot] = useState(null);
  const [me, setMe] = useState(null);
  const [networks, setNetworks] = useState(null);
  const [features, setFeatures] = useState({});
  const live = snapshot !== null;
  const data = snapshot || {};
  const { PEOPLE = [], POOL = [], FIELD_EVENTS = [], INTENTS = [] } = data;

  const refreshNetworks = React.useCallback(async () => {
    if (!nativeAuthed() || !window.IndexApp) return;
    try {
      let net = null;
      if (window.IndexApp.loadNetworks) {
        net = await window.IndexApp.loadNetworks();
      } else {
        const c = window.IndexApp.getClient && window.IndexApp.getClient();
        if (!c) return;
        const [listR] = await Promise.all([
          c.networks.list().catch(() => null),
          c.auth.me().catch(() => null),
        ]);
        if (!listR) return;
        const raw = window.IndexApp.normalizeList(listR, "networks");
        net = {
          networks: window.IndexApp.mapDiscoverNetworks
            ? raw.map((n) => window.IndexApp.mapDiscoverNetworks([{ ...n, isMember: true }])[0])
            : raw.map((n) => ({ id: n.id, name: n.title || n.name || "untitled", joined: true })),
        };
      }
      if (!net || !Array.isArray(net.networks)) return;
      setNetworks(net.networks);
      Object.assign(window.INDEX_DATA, { NETWORKS: net.networks });
    } catch (e) { /* keep prior list */ }
  }, []);

  // Re-fetch the signal shelf after pause/archive (or whenever the hub remounts)
  // so row status matches the backend without a full app reload.
  const refreshIntents = React.useCallback(async () => {
    if (!nativeAuthed() || !window.IndexApp) return;
    try {
      const loaded = await window.IndexApp.loadSnapshot();
      if (!loaded || !loaded.snapshot) return;
      const intents = loaded.snapshot.INTENTS || [];
      setSnapshot((prev) => (prev ? { ...prev, INTENTS: intents } : loaded.snapshot));
      Object.assign(window.INDEX_DATA, { INTENTS: intents });
    } catch (e) { /* keep prior list */ }
  }, []);

  // Optimistic shelf update after pause/archive lands locally, before refresh.
  const patchIntentStatus = React.useCallback((intentId, nextStatus) => {
    const apply = window.IndexApi && window.IndexApi.applyMappedIntentStatus;
    if (!apply || !intentId) return;
    setSnapshot((prev) => {
      if (!prev || !Array.isArray(prev.INTENTS)) return prev;
      const INTENTS = apply(prev.INTENTS, intentId, nextStatus);
      if (INTENTS === prev.INTENTS) return prev;
      Object.assign(window.INDEX_DATA, { INTENTS });
      return { ...prev, INTENTS };
    });
  }, []);
  const [people, setPeople] = useState([]);
  const [conversation, setConversation] = useState([]);
  const [field, setField] = useState([]);
  const [simRate, setSimRate] = useState(1);

  // ---- deep links (index:// and universal links) --------------------------
  // Swift forwards the raw URL it was handed and decides nothing about it;
  // window.IndexApi.parseDeepLink (apps/mac/api/deeplink.mjs, unit tested) is
  // the only place a URL turns into a route.
  const [notice, setNotice] = useState(null);
  const [pendingLink, setPendingLink] = useState(null);   // parsed route, not applied yet
  const [linkedCard, setLinkedCard] = useState(null);     // { person, route } on screen
  const [linkedChat, setLinkedChat] = useState(null);     // { person, conversationId } on screen
  // Bumped when a question link lands, so the signal's feed scrolls to it even
  // if that signal was already open and nothing else changed.
  const [focusQuestion, setFocusQuestion] = useState(0);

  useEffect(() => {
    if (!window.IndexApp || !window.IndexApp.onDeepLink) return;
    return window.IndexApp.onDeepLink((url) => {
      const deepLinkHosts = Array.isArray(window.INDEX_NATIVE?.deepLinkHosts)
        && window.INDEX_NATIVE.deepLinkHosts.length
        ? { hosts: window.INDEX_NATIVE.deepLinkHosts }
        : undefined;
      const route = (window.IndexApi && window.IndexApi.parseDeepLink)
        ? window.IndexApi.parseDeepLink(url, deepLinkHosts)
        : null;
      if (!route) {
        // Not ours: stay quiet. Direct or manual invocation can still provide
        // a recognized-host URL the app cannot route; AASA excludes deeper
        // web-only profile paths before normal macOS delivery.
        const ours = (window.IndexApi && window.IndexApi.isIndexDeepLink)
          ? window.IndexApi.isIndexDeepLink(url, deepLinkHosts)
          : false;
        if (ours) setNotice("that link doesn't open in the app — view it on index.network.");
        return;
      }
      if (route.route === "legacy-connect") {
        // Connect links were retired; there is nothing left to resolve them to.
        setNotice("this link is no longer supported — open the opportunity from your radar.");
        return;
      }
      setPendingLink(route);
    });
  }, []);

  // The resolver reads the radar through a ref, and a link already in flight is
  // never started twice. Depending on `people` (or restarting on a screen
  // change) would cancel and re-issue the fallback fetch on every radar update:
  // a duplicate GET /opportunities/:id at best, and in demo mode the periodic
  // sim tick could keep restarting it so the link never lands on a card or a
  // notice at all. One pending link resolves once, and always terminates.
  const peopleRef = useRef(people);
  peopleRef.current = people;
  const resolvingRef = useRef(null);

  // A link can arrive at the login screen or mid-boot (cold launch is the
  // normal case). Hold it there and apply it once the snapshot is in, rather
  // than resolving it against data that hasn't loaded.
  useEffect(() => {
    if (!pendingLink || screen === "login" || screen === "building") return;
    if (resolvingRef.current === pendingLink) return;   // already resolving this one
    const link = pendingLink;
    resolvingRef.current = link;
    (async () => {
      // A conversation belongs to a signal, so open that signal on the thread.
      // The floating chat is what is left when the signal is gone: the thread
      // still reads, it just has no session to live in.
      if (link.route === "conversation") {
        const target = await resolveDeepLinkConversation(link, peopleRef.current);
        if (resolvingRef.current !== link) return;
        resolvingRef.current = null;
        const intent = target && findIntent(target.intentId);
        if (intent) {
          openIntentOn(intent, { kind: "chat", personId: target.person.id });
        } else if (target) {
          setLinkedChat(target);
        } else {
          setNotice("couldn't open that conversation.");
        }
        setPendingLink(null);
        return;
      }
      // A question names its signal directly: it is answered in that signal's
      // own conversation with its agent, and nowhere else.
      if (link.route === "signal") {
        const intent = findIntent(link.id);
        resolvingRef.current = null;
        if (intent) {
          pickExistingIntent(intent);
          setFocusQuestion(Date.now());
        } else {
          setNotice("that signal isn't on your hub.");
        }
        setPendingLink(null);
        return;
      }
      const person = await resolveDeepLinkPerson(link, peopleRef.current);
      // A newer link arrived mid-flight and owns the slot now; let it finish.
      if (resolvingRef.current !== link) return;
      resolvingRef.current = null;
      // An opportunity is read inside the signal that surfaced it. A profile
      // link names no signal at all, so it stays a floating card, as does an
      // opportunity whose signal has left the hub.
      const owner = link.route === "card" && person ? findIntent(person.intentId) : null;
      if (owner) {
        openIntentOn(owner, { kind: "profile", personId: person.id, status: person.status });
      } else if (person) {
        setLinkedCard({ person, route: link.route });
      } else {
        setNotice(link.route === "card"
          ? "that opportunity isn't on your radar."
          : "couldn't open that profile.");
      }
      setPendingLink(null);
    })();
  }, [pendingLink, screen]);

  // Desktop notification pipeline: runs app-wide while signed in. The native
  // side never toasts while the app is frontmost, so this can stay up across
  // every screen; the identity gate (own-message suppression) rides on me.id.
  const meId = me && me.id;
  useEffect(() => {
    if (!live || !meId || !window.IndexApp || !window.IndexApp.startDesktopNotifications) return;
    return window.IndexApp.startDesktopNotifications({ getUserId: () => meId });
  }, [live, meId]);

  // React to native login/logout coming from the Swift shell.
  useEffect(() => {
    if (!window.IndexApp) return;
    // Reload can finish (and set INDEX_NATIVE.authenticated) before this
    // subscriber is attached. Re-read so a signed-in Reload does not stick
    // on the login screen from a stale document-start snapshot.
    if (nativeAuthed()) setScreen("building");
    return window.IndexApp.onAuthChanged((authenticated) => {
      if (authenticated) {
        setScreen("building");
      } else {
        setSnapshot(null); setMe(null); setNetworks(null);
        setConfirmedName(""); setEnriched(null);
        Object.assign(window.INDEX_DATA, { NETWORKS: [] });
        // Drop the whole deep-link pipeline, not just what is on screen: a
        // resolve still in flight would otherwise render a counterpart's card
        // over the login screen. Clearing resolvingRef makes the in-flight
        // resolve fail its own ownership check and bail when it completes.
        setLinkedCard(null);
        setLinkedChat(null);
        setPendingLink(null);
        resolvingRef.current = null;
        setScreen("login");
      }
    });
  }, []);

  // The "building" screen doubles as the boot loader: fetch the live snapshot,
  // then drop into the signals hub. Falls back to demo data when unauthenticated.
  // Two GETs and no artificial floor: the real wait at first run is the lookup
  // after the name card, and padding this one only made the same window appear
  // twice in a few seconds.
  useEffect(() => {
    if (screen !== "building") return;
    let cancelled = false;
    (async () => {
      let loaded = null;
      if (nativeAuthed() && window.IndexApp) {
        loaded = await window.IndexApp.loadSnapshot().catch(() => null);
      }
      if (cancelled) return;
      let needsProfile = false;
      if (loaded) {
        applyLoaded(loaded);
        setFreshUser((loaded.snapshot.INTENTS || []).length === 0);
        // Durable gate: a user who hasn't confirmed their profile yet reviews it
        // now, whether this is a fresh sign-in or a relaunch mid-onboarding.
        const ob = loaded.raw && loaded.raw.user && loaded.raw.user.onboarding;
        needsProfile = !(ob && ob.profileConfirmedAt);
        // Networks load in parallel with the loader animation; no cancelled guard
        // here — the building effect cleanup would discard the update otherwise.
        refreshNetworks();
      }
      setScreen(needsProfile ? "name" : "intents");
    })();
    return () => { cancelled = true; };
  }, [screen, refreshNetworks]);

  // First run, behind the same loader window: the public-research lookup, run on
  // the name just confirmed rather than on whatever the handshake happened to
  // supply. Nothing found is not a failure, the review just opens empty.
  useEffect(() => {
    if (screen !== "looking-up") return;
    let cancelled = false;
    (async () => {
      const res = (nativeAuthed() && window.IndexApp && window.IndexApp.triggerEnrichment)
        ? await window.IndexApp.triggerEnrichment({ name: confirmedName }).catch(() => null)
        : null;
      if (cancelled) return;
      setEnriched(res);
      setScreen("onboarding");
    })();
    return () => { cancelled = true; };
  }, [screen, confirmedName]);

  // Fold a loaded snapshot into React state and mirror ME/NETWORKS/INTENTS onto
  // window.INDEX_DATA so the side screens (settings/networks) that still read it
  // directly show live data without prop threading.
  const applyLoaded = (loaded) => {
    setSnapshot(loaded.snapshot);
    setMe(loaded.me);
    setFeatures(loaded.features || {});
    setPeople([
      ...(loaded.snapshot.PEOPLE || []).map(p => ({ ...p, hidden: false })),
      ...(loaded.snapshot.POOL || []).map(p => ({ ...p, hidden: true })),
    ]);
    Object.assign(window.INDEX_DATA, {
      ME: loaded.me,
      INTENTS: loaded.snapshot.INTENTS || [],
    });
  };

  const signOut = () => {
    if (window.IndexApp && window.IndexApp.logout()) {
      // onAuthChanged will reset the UI once Swift confirms.
      return;
    }
    setSnapshot(null); setMe(null); setNetworks(null);
    setConfirmedName(""); setEnriched(null);
    Object.assign(window.INDEX_DATA, { NETWORKS: [] });
    setScreen("login");
  };

  // Bridge: MainView publishes its chats (per active signal) up here so the top
  // menubar can show a 2-step menu, signals, and the chats within each, and
  // it persists across screens (so it works from the landing screen too).
  const [chatGroups, setChatGroups] = useState({}); // signalTitle -> [{id,name,unread}]
  const chatOpenRef = useRef(null);                  // { signal, open } for the active session
  // What to open inside a signal once it mounts: { kind: "chat" | "profile",
  // personId, status }. The menubar resumes a signal on a chat; a deep link can
  // also land on a profile, and carries the status so the radar opens on the
  // stage that person is actually in.
  const [pendingFocus, setPendingFocus] = useState(null);
  const registerChats = (signal, list, openFn) => {
    if (!signal) return;
    setChatGroups(prev => ({ ...prev, [signal]: list }));
    chatOpenRef.current = { signal, open: openFn };
  };

  // The screens the native menus can open: settings, networks and negotiations
  // (null = none, `tab` applies to settings only). They live up here rather than
  // in the hub because Index ▸ Settings… and the View menu have to work from a
  // signal too, and they open over whatever is on screen so neither the hub nor
  // a live signal session is torn down to show them.
  const [overlay, setOverlay] = useState(null);
  const closeOverlay = () => setOverlay(null);
  // Index ▸ Settings… and the View menu call this. Before the hub there is no
  // account behind the screen, which is also why those items are dimmed there.
  useEffect(() => {
    const reachable = screen === "intents" || screen === "main";
    window.__indexOpenView = (view) => { if (reachable) setOverlay({ view, tab: "profile" }); };
    return () => { delete window.__indexOpenView; };
  }, [screen]);

  const [accStats, setAccStats] = useState({ inspected: 47, online: 62 });
  useInterval(() => {
    setAccStats(s => ({
      inspected: s.inspected + (Math.random() < 0.7 ? 1 : 0) + (Math.random() < 0.3 ? 1 : 0),
      online:    s.online + (Math.random() < 0.5 ? 1 : -1),
    }));
  }, screen === "main" ? Math.max(900, 2500 / simRate) : null);

  const stats = useMemo(() => {
    const visible = people.filter(p => !p.hidden);
    const by = (s) => visible.filter(p => p.status === s).length;
    return {
      inspected: accStats.inspected,
      online: Math.max(40, accStats.online),
      surfaced: visible.filter(p => p.status !== "passed").length,
      negotiating: by("negotiating"),
      ready: by("ready"),
      warm: by("warm"),
      considering: by("considering"),
      passed: by("passed"),
      pool: people.filter(p => p.hidden).length,
    };
  }, [people, accStats]);

  const seedField = () => {
    setTimeout(() => {
      const seeds = FIELD_EVENTS.slice(0, 4).map(e => ({
        ...e, id: Math.random().toString(36).slice(2), t: Date.now(),
      }));
      setField(seeds);
    }, 400);
  };
  const profileFromIntent = (intent) => ({
    intentId: intent.id,
    intent: intent.title,
    status: intent.status,
  });
  const pickExistingIntent = (intent) => {
    // App-level feeds persist across signals; clear them so the previous
    // signal's questions and radar never flash into the next open.
    setConversation([]);
    setField([]);
    setPeople([]);
    setProfile(profileFromIntent(intent));
    setScreen("main");
    seedField();
  };
  const findIntent = (id) => (id ? (INTENTS || []).find((i) => i.id === id) || null : null);
  // Resume a signal and say what to open inside it once the session mounts.
  const openIntentOn = (intent, focus) => { pickExistingIntent(intent); setPendingFocus(focus); };
  const goNewIntent = () => setScreen("new-intent");
  const finishNewIntent = async (answers, created, intentId) => {
    setConversation([]);
    setField([]);
    setPeople([]);
    setFreshUser(false);   // they've created a signal, hub is no longer empty

    // Open the exact persisted signal as soon as POST /intents returns its ID.
    // The shelf refresh is background work, not a second blocking
    // /auth/me + /intents/list bootstrap.
    if (created && intentId) {
      const now = new Date().toISOString();
      const optimistic = {
        id: intentId,
        title: answers.intent || "new signal",
        status: "active",
        source: { id:intentId, createdAt:now, updatedAt:now },
      };
      setSnapshot((current) => {
        const INTENTS = [optimistic, ...((current && current.INTENTS) || []).filter((intent) => intent.id !== intentId)];
        Object.assign(window.INDEX_DATA, { INTENTS });
        return current ? { ...current, INTENTS } : { INTENTS };
      });
      setProfile(profileFromIntent(optimistic));
      setScreen("main");
      seedField();
      void refreshIntents();
      if (window.IndexApp && window.IndexApp.completeOnboarding) {
        void window.IndexApp.completeOnboarding(intentId).catch(() => {});
      }
      return;
    }

    setProfile({ intent: answers.intent });
    setScreen("main");
    seedField();
  };

  // Open a chat from the menubar. If its signal is the active session, open it
  // directly; otherwise resume that signal first, then open once main mounts.
  const openChatFromMenu = (signal, personId) => {
    if (screen === "main" && chatOpenRef.current && chatOpenRef.current.signal === signal) {
      chatOpenRef.current.open(personId);
    } else {
      const intent = INTENTS.find(i => i.title === signal);
      if (intent) openIntentOn(intent, { kind: "chat", personId });
    }
  };

  const startLogin = () => {
    if (window.IndexApp && window.IndexApp.login()) {
      // Native bridge present: wait for __indexAuthChanged; Login shows waiting.
      return true;
    }
    // No native bridge (browser preview): live-only, so there is nothing to
    // show without a real session. Stay on the sign-in screen.
    return false;
  };

  return (
    <IndexDataContext.Provider value={{ data, me, networks, features, live, refreshNetworks, refreshIntents, patchIntentStatus }}>
      <div style={{
        position:"fixed", inset:0,
        overflow:"hidden",
      }} className="mac-desktop">
        {screen === "login"       && <Login onSignIn={startLogin}/>}
        {/* Boot loader: assembles the live snapshot, then opens the hub. */}
        {screen === "building"    && <BuildingProfile/>}
        {screen === "intents"     && <Intents
                                       fresh={freshUser}
                                       onPickExisting={pickExistingIntent}
                                       onNew={goNewIntent}
                                       onOpenView={(view, tab) => setOverlay({ view, tab })}
                                       onSignOut={signOut}/>}
        {screen === "new-intent"  && <NewIntent onDone={finishNewIntent} onBack={() => setScreen("intents")}/>}
        {/* First run, in three screens: confirm the name, look the person up
            behind the loader, then review what came back. The review is what
            PATCHes profile + confirm-profile; the first signal after it POSTs
            onboarding/complete. */}
        {screen === "name"        && <AskName
                                       initialName={(me && me.name) || ""}
                                       onSubmit={(name) => { setConfirmedName(name); setScreen("looking-up"); }}
                                       onSignOut={signOut}/>}
        {screen === "looking-up"  && <BuildingProfile
                                       title="looking you up"
                                       lines={[
                                         "looking you up…",
                                         "reading what's already public…",
                                         "almost there.",
                                       ]}/>}
        {screen === "onboarding"  && <Settings
                                       initialTab="profile"
                                       profileOnly
                                       firstRun
                                       enriched={enriched}
                                       name={confirmedName}
                                       onClose={signOut}
                                       onDone={() => { setFreshUser((INTENTS || []).length === 0); setScreen("new-intent"); }}/>}
        {/* A deep-linked card floats over whatever screen is showing: the link
            can land on the hub, where the radar's selection state doesn't
            exist. */}
        {linkedCard && (
          <DeepLinkWindow
            person={linkedCard.person}
            route={linkedCard.route}
            onClose={() => setLinkedCard(null)}
          />
        )}
        {linkedChat && (
          <DeepLinkChatWindow
            person={linkedChat.person}
            conversationId={linkedChat.conversationId}
            onClose={() => setLinkedChat(null)}
          />
        )}
        {/* These lay over the desktop instead of replacing the screen, so
            leaving one drops you back into the same hub or signal. */}
        {overlay && (
          <div className="mac-desktop" style={{ position:"fixed", inset:0, zIndex:850 }}>
            {overlay.view === "settings" && <Settings initialTab={overlay.tab} onClose={closeOverlay}/>}
            {overlay.view === "networks" && (
              <Networks
                onClose={closeOverlay}
                onOpenSignal={(sig) => {
                  const intent = (window.INDEX_DATA.INTENTS || []).find(s => s.id === sig.id);
                  closeOverlay();
                  if (intent) pickExistingIntent(intent);
                }}
              />
            )}
            {overlay.view === "negotiations" && <NegotiationHistory onClose={closeOverlay}/>}
          </div>
        )}
        {notice && <MacNotice text={notice} onDismiss={() => setNotice(null)}/>}
        {screen === "main"        && (
          <MainView
            profile={profile}
            people={people} setPeople={setPeople}
            conversation={conversation} setConversation={setConversation}
            field={field} setField={setField}
            stats={stats}
            simRate={simRate} setSimRate={setSimRate}
            onBack={() => setScreen("intents")}
            registerChats={registerChats}
            pendingFocus={pendingFocus}
            onPendingHandled={() => setPendingFocus(null)}
            focusQuestion={focusQuestion}
          />
        )}
      </div>
    </IndexDataContext.Provider>
  );
}

function MacMenubar({ screen, signals = [], chatGroups = {}, onOpenChat }) {
  const [clock, setClock] = useState(macClock());
  const [chatsOpen, setChatsOpen] = useState(false);
  const [expanded, setExpanded] = useState(null); // which signal is expanded
  useEffect(() => {
    const t = setInterval(() => setClock(macClock()), 30000);
    return () => clearInterval(t);
  }, []);
  const groupUnread = (title) => (chatGroups[title] || []).reduce((a, c) => a + (c.unread || 0), 0);
  const totalUnread = signals.reduce((a, s) => a + groupUnread(s.title), 0);
  const rowHover = (on) => (e) => {
    e.currentTarget.style.background = on ? "#000" : "#fff";
    e.currentTarget.style.color = on ? "#FF8A00" : "#000";
  };
  return (
    <div className="mac-menubar">
      <span className="m bold">index</span>

      <span className="right">
        <span className="m subtle">
          { screen === "intents"    ? "your signals"
          : screen === "new-intent" ? "calibrating"
          : "" }
        </span>
        <span className="clock">{clock}</span>
      </span>
    </div>
  );
}
function macClock(){
  const d = new Date();
  let h = d.getHours(), m = String(d.getMinutes()).padStart(2,"0");
  const ampm = h >= 12 ? "PM" : "AM";
  h = h % 12 || 12;
  return `${h}:${m} ${ampm}`;
}

ReactDOM.createRoot(document.getElementById("root")).render(<App/>);


export { App };
export default App;
